t\",\"kode\":\"BK-0005\",\"isbn\":\"9780008376055\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:14:31'),(97,1,'tambah','buku',6,'{\"judul\":\"Animal Farm\",\"kode\":\"BK-0006\",\"isbn\":\"9780451525369\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:14:37'),(98,1,'tambah','buku',7,'{\"judul\":\"Nineteen Eighty-Four\",\"kode\":\"BK-0007\",\"isbn\":\"9780141391700\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:14:43'),(99,1,'tambah','buku',8,'{\"judul\":\"The Catcher in the Rye\",\"kode\":\"BK-0008\",\"isbn\":\"9780553239768\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:14:56'),(100,1,'tambah','buku',9,'{\"judul\":\"To Kill a Mockingbird\",\"kode\":\"BK-0009\",\"isbn\":\"9780061743528\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:15:05'),(101,1,'tambah','buku',10,'{\"judul\":\"Le petit prince\",\"kode\":\"BK-0010\",\"isbn\":\"9780152048044\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:15:15'),(102,1,'tambah','buku',11,'{\"judul\":\"Het Achterhuis\",\"kode\":\"BK-0011\",\"isbn\":\"9780141032009\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:15:22'),(103,1,'tambah','buku',12,'{\"judul\":\"Fahrenheit 451\",\"kode\":\"BK-0012\",\"isbn\":\"9780552092388\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:15:36'),(104,1,'tambah','buku',13,'{\"judul\":\"The Kite Runner\",\"kode\":\"BK-0013\",\"isbn\":\"9781594480003\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:15:41'),(105,1,'tambah','buku',14,'{\"judul\":\"The Book Thief\",\"kode\":\"BK-0014\",\"isbn\":\"9780385754729\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:15:48'),(106,1,'tambah','buku',15,'{\"judul\":\"The picture of Dorian Gray and other writings\",\"kode\":\"BK-0015\",\"isbn\":\"9781452896304\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:15:55'),(107,1,'tambah','buku',16,'{\"judul\":\"The Great Gatsby\",\"kode\":\"BK-0016\",\"isbn\":\"9780743273565\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:16:02'),(108,1,'tambah','buku',17,'{\"judul\":\"The Hobbit\",\"kode\":\"BK-0017\",\"isbn\":\"9780345534835\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:16:08'),(109,1,'tambah','buku',18,'{\"judul\":\"Animal Farm\",\"kode\":\"BK-0018\",\"isbn\":\"9781299886322\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:16:15'),(110,1,'tambah','buku',19,'{\"judul\":\"The Catcher in the Rye\",\"kode\":\"BK-0019\",\"isbn\":\"9780553117226\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:16:20'),(111,1,'tambah','buku',20,'{\"judul\":\"To Kill a Mockingbird\",\"kode\":\"BK-0020\",\"isbn\":\"9780061980268\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:16:26'),(112,1,'tambah','buku',21,'{\"judul\":\"The Diary of a Young Girl- Anne Frank\",\"kode\":\"BK-0021\",\"isbn\":\"9780141971667\",\"via\":\"import_batch\",\"providers\":[\"Open Library\"]}','2026-09-24 01:16:33'),(113,1,'edit','buku',21,'{\"stok\":{\"dari\":1,\"ke\":5}}','2026-09-24 01:17:53'),(114,1,'edit','buku',20,'{\"stok\":{\"dari\":1,\"ke\":4}}','2026-09-24 01:18:00'),(115,1,'edit','buku',19,'{\"stok\":{\"dari\":1,\"ke\":0}}','2026-09-24 01:18:08'),(116,1,'edit','buku',19,'{\"stok\":{\"dari\":0,\"ke\":4}}','2026-09-24 01:18:14'),(117,1,'edit','buku',18,'{\"stok\":{\"dari\":1,\"ke\":7}}','2026-09-24 01:18:24'),(118,1,'hapus','buku',9,'{\"judul\":\"To Kill a Mockingbird\"}','2026-09-24 01:20:01'),(119,1,'hapus','buku',18,'{\"judul\":\"Animal Farm\"}','2026-09-24 01:20:19'),(120,1,'hapus','buku',6,'{\"judul\":\"Animal Farm\"}','2026-09-24 01:20:35');
