LOCK TABLES `buku` WRITE;
/*!40000 ALTER TABLE `buku` DISABLE KEYS */;
INSERT INTO `buku` VALUES (1,'BK-0001','9786239726201','Janji','Tere Liye','Sabak Grip Nusantara',2021,1,'Kita semua adalah pengembara di dunia ini.\r\nAda yang kaya, pun ada yang miskin. Ada yang terkenal, ternama, berkuasa, juga ada\r\nyang bukan siapa-siapa.\r\nAda yang seolah bisa membeli apapun, melakukan apapun yang dia mau, hebat sekali.\r\nAda yang bahkan bingung besok harus makan apa.\r\nTapi sesungguhnya di manakah kebahagiaan itu hinggap?\r\nDi manakah hakikat kehidupan itu tersembunyi?\r\nApakah seperti yang kita lihat dari luar saja?\r\nInilah kisah tentang janji.\r\nKita semua adalah pengembara di dunia ini.\r\nDari hari ke hari. Dari satu tempat ke tempat lain.\r\nDari satu kejadian ke kejadian lain. Terus mengembara.\r\nDan kita pasti akan menggenapkan janji yang satu ini: mati.','cover_6ab477d30fe60.jpg',5,5,0,NULL,'Rak A1','2026-09-24 01:07:31'),(2,'BK-0002','9782070415717','Foundation and Empire','Isaac Asimov','Denoel',1945,1,'Led by its founding father, the great psychohistorian Hari Seldon, and taking advantage of its superior science and technology, the Foundation has survived the greed and barbarism of its neighboring warrior-planets. Yet now it must face the Empire still the mightiest force in the Galaxy even in its death throes. When an ambitious general determined to restore the Empire\'s glory turns the vast Imperial fleet toward the Foundation, the only hope for the small planet of scholars and scientists lies in the prophecies of Hari Seldon.','cover_6ab478106c24a.jpg',5,5,0,NULL,'Rak A1','2026-09-24 01:08:32'),(3,'BK-0003','9789021012261','Four Past Midnight','Stephen King','Poema Pocket',1990,1,'Four Past Midnight is a collection of novellas written by Stephen King in 1988 and 1989 and published in August 1990. It is his second book of this type, the first one being Different Seasons. The collection won the Bram Stoker Award in 1990 for Best Collection and was nominated for a Locus Award in 1991.\r\n\r\nOne Past Midnight: \"[The Langoliers][1]\" takes a red-eye flight from L.A. to Boston into a most unfriendly sky. Only eleven passengers survive, but landing in an eerily empty world makes them wish they hadn\'t. Something\'s waiting for them, you see....\r\n\r\nTwo Past Midnight: \"[Secret Window, Secret Garden][2]\" enters the suddenly strange life of writer Mort Rainey, recently divorced, depressed, and alone on the shore of Tashmore Lake. Alone, that is, until a figure named John Shooter arrives, pointing an accusing finger.\r\n\r\nThree Past Midnight: \"[The Library Policeman][3]\" is set in Junction City, Iowa, an unlikely place for evil to be hiding. But for small businessman Sam Peebles, who thinks he may be losing his mind, another enemy is hiding there as well--the truth. If he can find it in time, he might stand a chance.\r\n\r\nFour Past Midnight: The flat surface of a Polaroid photograph becomes for fifteen-year-old Kevin Delevan an invitation to the supernatural. Old Pop Merrill, Castle Rock\'s sharpest trader, wants to crash the party for profit, but \"[The Sun Dog][4],\" a creature that shouldn\'t exist at all, is a very dangerous investment.\r\n\r\n[1]: https://openlibrary.org/works/OL149138W/The_Langoliers\r\n[2]: https://openlibrary.org/works/OL14917476W/Secret_Window_Secret_Garden\r\n[3]: https://openlibrary.org/works/OL14917299W/The_Library_Policeman\r\n[4]: https://openlibrary.org/works/OL14916850W/The_Sun_Dog','cover_6ab4784ac29ce.jpg',4,4,0,NULL,'Rak A1','2026-09-24 01:09:30'),(7,'BK-0007','9780141391700','Nineteen Eighty-Four','George Orwell, George Orwell, Georges Orwell','Penguin Books, Limited',1949,1,'Nineteen Eighty-Four: A Novel, often referred to as 1984, is a dystopian social science fiction novel by the English novelist George Orwell (the pen name of Eric Arthur Blair). It was published on 8 June 1949 by Secker & Warburg as Orwell\'s ninth and final book completed in his lifetime. Thematically, Nineteen Eighty-Four centres on the consequences of totalitarianism, mass surveillance, and repressive regimentation of persons and behaviours within society. Orwell, himself a democratic socialist, modelled the authoritarian government in the novel after Stalinist Russia. More broadly, the novel examines the role of truth and facts within politics and the ways in which they are manipulated.\n\n----------\nAlso contained in:\n[Novels (Animal Farm / Burmese Days / Clergyman\'s Daughter / Coming Up for Air / Keep the Aspidistra Flying / Nineteen Eighty-Four)](https://openlibrary.org/works/OL1168045W)\n[Novels (Animal Farm / Nineteen Eighty-Four)](https://openlibrary.org/works/OL1167981W)\n[Orwell\'s Nineteen Eighty-Four: Text, Sources, Criticism](https://openlibrary.org/works/OL1168095W)','cover_6ab47983e25e0.jpg',1,1,0,NULL,NULL,'2026-09-24 01:14:43'),(10,'BK-0010','9780152048044','Le petit prince','Antoine de Saint-Exupéry','Harcourt Children\'s Books',1943,6,'*Le Petit Prince* est une œuvre de langue française, la plus connue d\'Antoine de Saint-Exupéry. Publié en 1943 à New York simultanément à sa traduction anglaise, c\'est une œuvre poétique et philosophique sous l\'apparence d\'un conte pour enfants.\n\nTraduit en quatre cent cinquante-sept langues et dialectes, *Le Petit Prince* est le deuxième ouvrage le plus traduit au monde setelah la Bible.\n\nLe langage, simple et dépouillé, parce qu\'il est destiné à être compris par des enfants, est en réalité pour le narrateur le véhicule privilégié d\'une conception symbolique de la vie. Chaque chapitre relate une rencontre du petit prince qui laisse celui-ci perplexe, par rapport aux comportements absurdes des « grandes personnes ». Ces différentes rencontres peuvent être lues comme une allégorie.\n\nLes aquarelles font partie du texte et participent à cette pureté du langage : dépouillement et profondeur sont les qualités maîtresses de l\'œuvre.\n\nOn peut y lire une invitation de l\'auteur à retrouver l\'enfant en soi, car « toutes les grandes personnes ont d\'abord été des enfants. (Mais peu d\'entre elles s\'en souviennent.) ». L\'ouvrage est dédié à Léon Werth, mais « quand il était petit garçon ».\n\n(Wikipedia)','cover_6ab479a3ab61b.jpg',1,1,0,NULL,NULL,'2026-09-24 01:15:15'),(11,'BK-0011','9780141032009','Het Achterhuis','Anne Frank','Penguin Books, Limited (UK)',1944,4,'Het Achterhuis is de titel van het dagboek van Anne Frank (1929-1945) voor het eerst uitgegeven op 25 juni 1947. Het is genoemd naar het onderduikpand Het Achterhuis op de Prinsengracht en is het verhaal van een ondergedoken jong Joods meisje ten tijde van de Tweede Wereldoorlog. Het is wereldwijd een van de meest gelezen boeken. Sinds 2009 staat Annes dagboek op de Werelderfgoedlijst voor documenten van UNESCO.\n\n----------\nAlso contained in:\n[Works of Anne Frank](https://openlibrary.org/works/OL2931445W)','cover_6ab479aa4c4a8.jpg',1,1,0,NULL,NULL,'2026-09-24 01:15:22'),(12,'BK-0012','9780552092388','Fahrenheit 451','Ray Bradbury','Corgi',1953,1,'Fahrenheit 451 is a 1953 dystopian novel by American writer Ray Bradbury. Often regarded as one of his best works, the novel presents a future American society where books are outlawed and \"firemen\" burn any that are found. The book\'s tagline explains the title as \"\'the temperature at which book paper catches fire, and burns\": the autoignition temperature of paper. The lead character, Guy Montag, is a fireman who becomes disillusioned with his role of censoring literature and destroying knowledge, eventually quitting his job and committing himself to the preservation of literary and cultural writings.\n\nThe novel has been the subject of interpretations focusing on the historical role of book burning in suppressing dissenting ideas for change. In a 1956 radio interview, Bradbury said that he wrote Fahrenheit 451 because of his concerns at the time (during the McCarthy era) about the threat of book burning in the United States. In later years, he described the book as a commentary on how mass media reduces interest in reading literature.\n\nIn 1954, Fahrenheit 451 won the American Academy of Arts and Letters Award in Literature and the Commonwealth Club of California Gold Medal. It later won the Prometheus \"Hall of Fame\" Award in 1984 and a \"Retro\" Hugo Award, one of a limited number of Best Novel Retro Hugos ever given, in 2004. Bradbury was honored with a Spoken Word Grammy nomination for his 1976 audiobook version.\n\n---\n\nAlso contained in:\n\n- [451° по Фаренгейту: Рассказы](https://openlibrary.org/works/OL17811384W/Fahrenheit_451_stories)\n- [451° по Фаренгейту: повести и рассказы](https://openlibrary.org/works/OL27741633W)\n- [Works](https://openlibrary.org/works/OL28185143W)','cover_6ab479b8483af.jpg',1,1,0,NULL,NULL,'2026-09-24 01:15:36'),(13,'BK-0013','9781594480003','The Kite Runner','Khaled Hosseini','Riverhead Books',2003,1,'The unforgettable, heartbreaking story of the unlikely friendship between a wealthy boy and the son of his father’s servant, The Kite Runner is a beautifully crafted novel set in a country that is in the process of being destroyed. It is about the power of reading, the price of betrayal, and the possibility of redemption; and an exploration of the power of fathers over sons—their love, their sacrifices, their lies.\n\nA sweeping story of family, love, and friendship told against the devastating backdrop of the history of Afghanistan over the last thirty years, The Kite Runner is an unusual and powerful novel that has become a beloved, one-of-a-kind classic.\n([source][1])\n\n[1]: https://khaledhosseini.com/books/the-kite-runner/','cover_6ab479bdb8c23.jpg',1,1,0,NULL,NULL,'2026-09-24 01:15:41'),(14,'BK-0014','9780385754729','The Book Thief','Markus Zusak','Alfred A. Knopf',1998,1,'It is 1939 Nazi Germany. The country is holding its breath.\nDeath has never been busier, and will become busier still.\n\nBy her brother\'s graveside, Liesel Meminger\'s life is changed when she picks up a single object, partially hidden in the snow. It is The Grave Digger\'s Handbook, left there by accident, and it is her first act of book thievery. So begins a love affair with books and words, as Liesel, with the help of her accordion-playing foster father, learns to read. Soon she is stealing books from Nazi book-burnings, the mayor\'s wife\'s library, wherever there are books to be found.\n\nBut these are dangerous times. When Liesel\'s foster family hides a Jew in their basement, Liesel\'s world is both opened up and closed down.\n\nIn superbly crafted writing that burns with intensity, award-winning author Markus Zusak has given us one of the most enduring stories of our time.\n\n--back cover','cover_6ab479c49957d.jpg',1,1,0,NULL,NULL,'2026-09-24 01:15:48'),(15,'BK-0015','9781452896304','The picture of Dorian Gray and other writings','Oscar Wilde','SoHoBooks',2014,2,'This is a story of love, murder, thwarted revenge, and finally, justice. As Dorian Gray remains young and handsome, his pact with the devil allows his portrait to reflect the degradation of his many sins.','cover_6ab479cb7164d.jpg',1,1,0,NULL,NULL,'2026-09-24 01:15:55'),(16,'BK-0016','9780743273565','The Great Gatsby','F. Scott Fitzgerald','Scribner',1920,1,'THE GREAT GATSBY, F. Scott Fitzgerald’s third book, stands as the supreme achievement of his career. This exemplary novel of the Jazz Age has been acclaimed by generations of readers. The story of the fabulously wealthy Jay Gatsby and his love for the beautiful Daisy Buchanan, of lavish parties on Long Island at a time when The New York Times noted “gin was the national drink and sex the national obsession,” is an exquisitely crafted tale of America in the 1920s.\n\nThe Great Gatsby is one of the great classics of twentieth-century literature.\n--back cover','cover_6ab479d251d78.jpg',1,1,0,NULL,NULL,'2026-09-24 01:16:02'),(17,'BK-0017','9780345534835','The Hobbit','J.R.R. Tolkien','Del Rey',1937,6,'The Hobbit is a tale of high adventure, undertaken by a company of dwarves in search of dragon-guarded gold. A reluctant partner in this perilous quest is Bilbo Baggins, a comfort-loving unambitious hobbit, who surprises even himself by his resourcefulness and skill as a burglar.\n\nEncounters with trolls, goblins, dwarves, elves, and giant spiders, conversations with the dragon, Smaug, and a rather unwilling presence at the Battle of Five Armies are just some of the adventures that befall Bilbo.\n\nBilbo Baggins has taken his place among the ranks of the immortals of children’s fiction. Written by Professor Tolkien for his children, The Hobbit met with instant critical acclaim when published.','cover_6ab479d8848d8.jpg',1,1,0,NULL,NULL,'2026-09-24 01:16:08'),(19,'BK-0019','9780553117226','The Catcher in the Rye','J. D. Salinger, Shao jia yun','Bantam Books',1945,1,'Story of Holden Caufield with his idiosyncrasies, penetrating insight, confusion, sensitivity and negativism. Holden, knowing he is to be expelled from school, decides to leave early. He spends three days in New York City and tells the story of what he did and suffered there.','cover_6ab479e4d84d0.jpg',4,4,0,NULL,'Rak A1','2026-09-24 01:16:20'),(20,'BK-0020','9780061980268','To Kill a Mockingbird','Harper Lee','HarperCollins',1960,1,'One of the best-loved stories of all time, To Kill a Mockingbird has been translated into more than 40 languages, sold more than 30 million copies worldwide, served as the basis for an enormously popular motion picture, and voted one of the best novels of the 20th century by librarians across the United States. A gripping, heart-wrenching, and wholly remarkable tale of coming-of-age in a South poisoned by virulent prejudice, it views a world of great beauty and savage inequities through the eyes of a young girl, as her father -- a crusading local lawyer -- risks everything to defend a black man unjustly accused of a terrible crime.\r\n\r\nLawyer Atticus Finch defends Tom Robinson -- a black man charged with the rape of a white girl. Writing through the young eyes of Finch\'s children Scout and Jem, Harper Lee explores with rich humor and unswerving honesty the irrationality of adult attitudes toward race and class in small-town Alabama during the mid-1930s Depression years. The conscience of a town steeped in prejudice, violence, and hypocrisy is pricked by the stamina and quiet heroism of one man\'s struggle for justice. But the weight of history will only tolerate so much.\r\n\r\n----------\r\nAlso contained in:\r\n\r\n- [Best Sellers from Reader\'s Digest Condensed Books](https://openlibrary.org/works/OL16035425W)','cover_6ab479eaa2c0d.jpg',4,4,0,NULL,'Rak A1','2026-09-24 01:16:26'),(21,'BK-0021','9780141971667','The Diary of a Young Girl- Anne Frank','Anne Frank','Penguin Books, Limited',2001,4,'The Diary of a Young Girl, also known as The Diary of Anne Frank, is a book of the writings from the Dutch-language diary kept by Anne Frank while she was in hiding for two years with her family during the Nazi occupation of the Netherlands. The family was apprehended in 1944, and Anne Frank died of typhus in the Bergen-Belsen concentration camp in 1945. Anne\'s diaries were retrieved by Miep Gies and Bep Voskuijl. Miep gave them to Anne\'s father, Otto Frank, the family\'s only survivor, just after the Second World War was over.','cover_6ab479f142c5c.jpg',5,5,0,NULL,'Rak A1','2026-09-24 01:16:33'),(22,'BK-0022','9780141439518','Pride and Prejudice','Jane Austen','Penguin Classics',0000,1,'Pride and Prejudice is a romantic novel of manners written by Jane Austen in 1813. The novel follows the character development of Elizabeth Bennet, the protagonist of the book, who learns about the repercussions of hasty judgments and comes to appreciate the difference between superficial goodness and actual goodness.','cover_add_547ff4a5.jpg',3,3,0,NULL,'Rak B1','2026-10-20 03:29:57'),(23,'BK-0023','9780141441146','Jane Eyre','Charlotte Brontë','Penguin Classics',0000,1,'Jane Eyre is a novel by English writer Charlotte Brontë, published under the pen name \"Currer Bell\", on 16 October 1847, by Smith, Elder & Co. of London. The novel is a first-person narrative of the title character, a young governess who falls in love with her brooding employer, Mr. Rochester.','cover_add_d7d0a118.jpg',3,3,0,NULL,'Rak B1','2026-10-20 03:29:57'),(24,'BK-0024','9780141439549','Wuthering Heights','Emily Brontë','Penguin Classics',0000,1,'Wuthering Heights is a novel by Emily Brontë published in 1847 under her pseudonym \"Ellis Bell\". It is her only finished novel. The story revolves around the intense, passionate, and ultimately doomed love between Heathcliff and Catherine Earnshaw, and how their unresolved passion eventually destroys them and those around them.','cover_add_4fe5beb.jpg',3,3,0,NULL,'Rak B1','2026-10-20 03:29:57'),(25,'BK-0025','9780142437241','Moby-Dick','Herman Melville','Penguin Classics',0000,1,'Moby-Dick; or, The Whale is an 1851 novel by American writer Herman Melville. The book is the sailor Ishmael\'s narrative of the obsessive quest of Ahab, captain of the whaling ship Pequod, for revenge on Moby Dick, the giant white sperm whale that bit off his leg on the ship\'s previous voyage.','cover_add_mobydick.jpg',2,2,0,NULL,'Rak B2','2026-10-20 03:29:57'),(26,'BK-0026','9780143058144','Crime and Punishment','Fyodor Dostoevsky','Penguin Classics',0000,1,'Crime and Punishment is a novel by the Russian author Fyodor Dostoevsky. It was first published in the literary journal The Russian Messenger in twelve monthly installments during 1866. The story focuses on the mental anguish and moral dilemmas of Rodion Raskolnikov, an impoverished ex-student in Saint Petersburg who formulates a plan to kill an unscrupulous pawnbroker.','cover_add_1fa6b57a.jpg',2,2,0,NULL,'Rak B2','2026-10-20 03:29:57'),(27,'BK-0027','9780140444308','Les Misérables','Victor Hugo','Penguin Classics',0000,1,'Les Misérables is a French historical novel by Victor Hugo, first published in 1862, that is considered one of the greatest novels of the 19th century. The novel follows the lives and interactions of several characters, particularly the struggles of ex-convict Jean Valjean and his experience of redemption.','cover_add_be1d2c9.jpg',2,2,0,NULL,'Rak B2','2026-10-20 03:29:57'),(28,'BK-0028','9786028708148','Laskar Pelangi','Andrea Hirata','Bentang Pustaka',2005,1,'Laskar Pelangi adalah novel karya Andrea Hirata yang menceritakan tentang sekelompok anak-anak dari Belitung yang berjuang meraih pendidikan meskipun berbagai keterbatasan. Novel ini menjadi salah satu novel Indonesia yang paling banyak dibaca dan diadaptasi ke film.','cover_alt_a89a0731.jpg',5,5,0,NULL,'Rak C1','2026-10-20 03:29:57'),(29,'BK-0029','9786020301129','Bumi','Tere Liye','Sabak Grip Nusantara',2014,1,'Bumi adalah novel pertama dari seri Bumi tetralogy karya Tere Liye. Cerita tentang Raisa dan Ragil yang harus melangkah ke dunia baru dengan tantangan dan misteri yang menanti.','cover_add_926e812b.jpg',5,5,0,NULL,'Rak C1','2026-10-20 03:29:57'),(30,'BK-0030','9789793062428','Ayat-Ayat Cinta','Habiburrahman El Shirazy','Republika Penerbit',2004,1,'Ayat-Ayat Cinta menceritakan perjuangan Fahri, seorang mahasiswa Islam Mesir, dalam mencintai dan menjaga iman di tengah tantangan budaya dan agama di negeri asing.','cover_alt_1dab4dca.jpg',4,4,0,NULL,'Rak C2','2026-10-20 03:29:57'),(31,'BK-0031','9786028270429','Cinta Brontosaurus','Raditya Dika','Gramedia Pustaka Utama',2010,6,'Kumpulan cerita pendek humoris Raditya Dika tentang pengalaman cinta yang tidak berjalan lancar, diceritakan dengan gaya kocak yang khas penulis.',NULL,4,4,0,NULL,'Rak C2','2026-10-20 03:29:57'),(32,'BK-0032','9786020326542','Supernova: Ksatria, Puteri, dan Bintang Jatuh','Dee Lestari','Bentang Pustaka',2001,1,'Novel Supernova pertama dari Dee Lestari tentang Reyna dan Dimas, dua sahabat yang saling menyukai tetapi terhalang oleh berbagai hal, di latar belakang dunia musik.','cover_alt_40555ddc.jpg',4,4,0,NULL,'Rak C3','2026-10-20 03:29:57'),(33,'BK-0033','9786029164088','5 cm','Donny Dhirgantoro','Republika Penerbit',2010,1,'5 cm menceritakan tentang lima teman dekat yang mendaki Gunung Semeru untuk meraih impian dan menebus rasa kesedihan atas kehilangan salah satu teman mereka.','cover_alt_a32fb4ee.jpg',3,3,0,NULL,'Rak C3','2026-10-20 03:29:57'),(34,'BK-0034','9786020324784','Hujan','Tere Liye','Sabak Grip Nusantara',2016,1,'Hujan adalah novel karya Tere Liye yang menceritakan tentang Aka dan Nida, dua saudara yang memiliki hubungan istimewa dan petualangan mereka yang memukau.','cover_add_c3e3605a.jpg',4,4,0,NULL,'Rak C1','2026-10-20 03:29:57'),(35,'BK-0035','9786020313689','Bulan','Tere Liye','Sabak Grip Nusantara',2015,1,'Bulan menceritakan tentang Kevin yang pindah ke rumah baru dan bertemu dengan Rahman serta putrinya, Alya. Cerita misteri dengan nuansa fantasi yang mengembang.','cover_alt_2fd18867.jpg',4,4,0,NULL,'Rak C1','2026-10-20 03:29:57'),(36,'BK-0036','9786020323901','Bintang','Tere Liye','Sabak Grip Nusantara',2018,1,'Bintang adalah sequel dari novel Bulan. Cerita melanjutkan petualangan Kevin, Alya, dan Rahman dalam mengungkap rahasia di sekitar kehidupan mereka.','cover_alt_c2e1089e.jpg',3,3,0,NULL,'Rak C1','2026-10-20 03:29:57'),(37,'BK-0037','9786020332116','Matahari','Tere Liye','Sabak Grip Nusantara',2018,1,'Matahari menceritakan tentang Zafran yang memiliki kemampuan khusus dan petualangannya bersama Rebekah untuk menyelamatkan dunia dari ancaman.','cover_add_6dddf6a9.jpg',3,3,0,NULL,'Rak C1','2026-10-20 03:29:57'),(38,'BK-0038','9780062315007','The Alchemist','Paulo Coelho','HarperOne',1988,1,'The Alchemist is a novel by Brazilian author Paulo Coelho that follows the journey of Santiago, a young Andalusian shepherd who travels to Egypt in search of a treasure.','cover_add_5446701e.jpg',4,4,0,NULL,'Rak D1','2026-10-20 03:29:57'),(39,'BK-0039','9780747532699','Harry Potter and the Philosopher\'s Stone','J.K. Rowling','Bloomsbury',1997,6,'Harry Potter discovers he is a wizard on his eleventh birthday and attends Hogwarts School of Witchcraft and Wizardry, where he learns about his past and faces the dark wizard Voldemort.','cover_add_8d4ce021.jpg',6,6,0,NULL,'Rak D2','2026-10-20 03:29:57'),(40,'BK-0040','9780451526342','Animal Farm','George Orwell','Signet Classic',1945,1,'Animal Farm is an allegorical novella by George Orwell about a group of farm animals who rebel against their human farmer, hoping to create a society where animals can be equal, free, and happy.','cover_add_f71d20a7.jpg',3,3,0,NULL,'Rak D2','2026-10-20 03:29:57'),(41,'BK-0041','9780141439471','Frankenstein','Mary Shelley','Penguin Classics',0000,1,'Frankenstein; or, The Modern Prometheus is a novel written by Mary Shelley about Victor Frankenstein, a scientist who creates a hideous creature in an unorthodox scientific experiment.','cover_add_dc9a7952.jpg',2,2,0,NULL,'Rak D3','2026-10-20 03:29:57'),(42,'BK-0042','9780141439570','The Picture of Dorian Gray','Oscar Wilde','Penguin Classics',0000,2,'The Picture of Dorian Gray is a Gothic and philosophical novel by Oscar Wilde about a man whose portrait ages and records his sins while he remains youthful.','cover_add_addd1fed.jpg',2,2,0,NULL,'Rak D3','2026-10-20 03:29:57'),(43,'BK-0043','9780307474278','The Da Vinci Code','Dan Brown','Doubleday',2003,1,'The Da Vinci Code is a mystery thriller novel by Dan Brown that follows symbologist Robert Langdon and cryptologist Sophie Neveu after a murder in the Louvre Museum.','cover_add_7c8254da.jpg',5,5,0,NULL,'Rak D1','2026-10-20 03:29:57'),(44,'BK-0044','9780060883287','One Hundred Years of Solitude','Gabriel García Márquez','Harper Perennial',1967,1,'One Hundred Years of Solitude is a landmark novel by Gabriel García Márquez that tells the story of the Buendía family over seven generations in the fictional town of Macondo.','cover_add_a1f32ac3.jpg',3,3,0,NULL,'Rak D3','2026-10-20 03:29:57'),(45,'BK-0045','9780156027326','Life of Pi','Yann Martel','Harcourt',2001,1,'Life of Pi is a novel by Yann Martel about Piscine Molitor Patel, an Indian boy who survives a shipwreck and is stranded in the Pacific Ocean on a lifeboat with a Bengal tiger.','cover_alt_ecddfde4.jpg',3,3,0,NULL,'Rak D1','2026-10-20 03:29:57'),(46,'BK-0046','9780307269754','The Girl with the Dragon Tattoo','Stieg Larsson','Norstedts',2005,1,'The Girl with the Dragon Tattoo is a psychological thriller by Stieg Larsson about journalist Mikael Blomkvist and hacker Lisbeth Salander investigating a decades-old disappearance.','cover_alt_d6e890fc.jpg',4,4,0,NULL,'Rak D2','2026-10-20 03:29:57'),(47,'BK-0047','9781400032618','The Curious Incident of the Dog in the Night-Time','Mark Haddon','Jonathan Cape',2003,6,'The Curious Incident of the Dog in the Night-Time is a mystery novel by Mark Haddon about Christopher Boone, a 15-year-old boy with autism who investigates the death of a neighbor\'s dog.','cover_alt_4519c95d.jpg',3,3,0,NULL,'Rak D2','2026-10-20 03:29:57'),(48,'BK-0048','9780140268867','The Odyssey','Homer','Penguin Classics',1999,1,'The Odyssey is one of two major ancient Greek epic poems attributed to Homer. It is, in part, a sequel to the Iliad, the other Homeric epic. The Odyssey is fundamental to the modern Western canon and is the second-oldest extant work of Western literature, while the Iliad is the oldest. Scholars believe the Odyssey was composed near the end of the 8th century BC, somewhere in Ionia, the Greek coastal region of Anatolia. The poem mainly focuses on the Greek hero Odysseus (known as Ulysses in Roman myths), king of Ithaca, and his journey home after the Trojan War. After the war itself, which lasted ten years, his journey lasted ten years during which he encountered many perils and all his crewmates were killed. In his absence, Odysseus was assumed dead, and his wife Penelope and son Telemachus had to contend with a group of unruly suitors who competed for Penelope\'s hand in marriage.','cover_30_4dff6998.jpg',3,3,0,NULL,'Rak A1','2026-10-20 03:29:57'),(49,'BK-0049','9780140449099','Don Quixote','Miguel de Cervantes','Penguin Classics',2003,1,'Don Quixote is a Spanish novel by Miguel de Cervantes. It was published in two parts, in 1605 and 1615. Considered a founding work of modern Western literature and one of the greatest novels ever written, it tells the story of Alonso Quixano, a Hidalgo who reads so many chivalric romances that he loses his mind and decides to become a knight-errant to revive chivalry and serve his nation, under the name Don Quixote de la Mancha. He recruits a simple farmer, Sancho Panza, as his squire, who often employs a unique, earthy wit in dealing with Don Quixote\'s rhetorical monologues on knighthood, considered outdated at the time. Don Quixote, in the first part of the book, does not see the world for what it is and prefers to imagine that he is living out a knightly story.','cover_30_fd997a0c.jpg',6,6,0,NULL,'Rak A1','2026-10-20 03:29:57'),(50,'BK-0050','9780143035008','Anna Karenina','Leo Tolstoy','Penguin Classics',2004,1,'Anna Karenina is a novel by the Russian author Leo Tolstoy, first published in book form in 1878. Many authors consider it to be one of the greatest works of literature ever written, and Tolstoy himself called it his first true novel. The novel is divided into eight parts. Its epigraph is \'Vengeance is mine; I will repay,\' from Romans 12:19. Initially published in serial installments from 1873 to 1877 in the periodical The Russian Messenger, the novel tells the tragic story of Anna Karenina, a married aristocrat and socialite, and her affair with the affluent officer Count Alexei Kirillovich Vronsky. The story unfolds in three main strands: Anna\'s tragic romance, Konstantin Levin\'s philosophical search for meaning, and Stepan Oblonsky\'s domestic troubles.','cover_30_2beac5af.jpg',8,8,0,NULL,'Rak A1','2026-10-20 03:29:57'),(51,'BK-0051','9780143039990','War and Peace','Leo Tolstoy','Penguin Classics',2007,1,'War and Peace is a literary work by the Russian author Leo Tolstoy that mixes fictional narrative with chapters on history and philosophy. First published serially from 1865 to 1869, it was later published in book form in 1869. The work is epic in scale and is regarded as one of the most important works of world literature. It is considered Tolstoy\'s finest literary achievement, along with his other major novel Anna Karenina (1873-1877). The novel chronicles the French invasion of Russia and the impact of the Napoleonic era on Tsarist society through the stories of five Russian aristocratic families. Portions of an earlier version, titled The Year 1805, were serialized in The Russian Messenger from 1865 to 1867 before the novel was published in its entirety in 1869.','cover_30_fc51d0ab.jpg',6,6,0,NULL,'Rak A1','2026-10-20 03:29:57'),(52,'BK-0052','9780140449234','The Brothers Karamazov','Fyodor Dostoevsky','Penguin Classics',2003,1,'The Brothers Karamazov is a novel by the Russian author Fyodor Dostoevsky, first published in book form in 1880. It is Dostoevsky\'s deepest and most complex novel, a passionate philosophical novel set in 19th-century Russia, that enters deeply into the ethical debates of God, free will, and morality. It is a spiritual drama of moral struggles concerning faith, doubt, and reason, set against a modernizing Russia. The novel centers on the murder of Fyodor Pavlovich Karamazov, a depraved landowner, and the investigation that follows, focusing on his three sons: Dmitri, the passionate and sensual eldest son; Ivan, the intellectual and skeptical middle son; and Alyosha, the gentle and spiritual youngest son.','cover_30_c61cdce8.jpg',2,2,0,NULL,'Rak A1','2026-10-20 03:29:57'),(53,'BK-0053','9780140449266','The Count of Monte Cristo','Alexandre Dumas','Penguin Classics',2003,1,'The Count of Monte Cristo is an adventure novel written by French author Alexandre Dumas (père) completed in 1844. It is one of the author\'s more popular works, along with The Three Musketeers. Like many of his novels, it was expanded from plot outlines suggested by his collaborating ghostwriter Auguste Maquet. The story takes place in France, Italy, and islands in the Mediterranean during the historical events of 1815-1839: the era of the Bourbon Restoration through the reign of Louis-Philippe of France. It begins just before the Hundred Days period (when Napoleon returned to power after his exile). The historical setting is a fundamental element of the book, an adventure story primarily concerned with themes of hope, justice, vengeance, mercy, and forgiveness. It tells the story of Edmond Dantès, who is falsely accused and imprisoned without trial in the Château d\'If, and his eventual escape and quest for revenge.','cover_30_48159eed.jpg',4,4,0,NULL,'Rak A1','2026-10-20 03:29:57'),(54,'BK-0054','9780062316097','Sapiens: A Brief History of Humankind','Yuval Noah Harari','Harper Perennial',2015,2,'Sapiens: A Brief History of Humankind is a book by Professor Yuval Noah Harari first published in Hebrew in Israel in 2011, and in English in 2014. The book surveys the history of humankind from the evolution of archaic human species in the Stone Age up to the twenty-first century, focusing on Homo sapiens. The account is situated within a framework that intersects the natural sciences with the social sciences. The book specifically uses a biological approach, but also incorporates approaches and insights from the social sciences and humanities. Harari divides the history of Sapiens into four major parts: the Cognitive Revolution, the Agricultural Revolution, the unification of humankind, and the Scientific Revolution. He explores how Homo sapiens came to dominate the planet, how we created shared myths like religion, money, and nations, and where our species might be headed in the future.','cover_30_6e3ad5bb.jpg',8,8,0,NULL,'Rak B1','2026-10-20 03:29:57'),(55,'BK-0055','9780374533557','Thinking, Fast and Slow','Daniel Kahneman','Farrar, Straus and Giroux',2011,2,'Thinking, Fast and Slow is a best-selling book published in 2011 by Nobel Memorial Prize in Economic Sciences laureate Daniel Kahneman. It was the 2012 winner of the National Academies Communication Award for best creative work that helps the public understanding of topics in behavioral science, engineering, and medicine. The book summarizes research that Kahneman conducted over decades, often in collaboration with Amos Tversky. It covers all three phases of his career: his early days working on cognitive biases, his work on prospect theory, and his later work on happiness. The central thesis is a dichotomy between two modes of thought: \'System 1\' is fast, instinctive and emotional; \'System 2\' is slower, more deliberative, and more logical. The book delineates cognitive biases associated with each type of thinking, beginning with Kahneman\'s own research on loss aversion.','cover_30_92d64550.jpg',1,1,0,NULL,'Rak B1','2026-10-20 03:29:57'),(56,'BK-0056','9780812981605','The Power of Habit','Charles Duhigg','Random House',2012,2,'The Power of Habit: Why We Do What We Do in Life and Business is a book by Charles Duhigg, a Pulitzer Prize-winning reporter for The New York Times, published in February 2012. It explores the science behind habits and how they can be changed. The book is divided into three sections that focus on the habits of individuals, organizations, and societies. Duhigg explains that habits operate on a neurological loop consisting of a cue, a routine, and a reward. By understanding this loop, individuals and organizations can identify and change destructive habits while building positive ones. The book includes case studies from various fields including business, sports, and medicine, illustrating how understanding habits can transform lives and organizations.','cover_30_c3412e6d.jpg',9,9,0,NULL,'Rak B1','2026-10-20 03:29:57'),(57,'BK-0057','9780735211292','Atomic Habits','James Clear','Avery',2018,2,'Atomic Habits: An Easy & Proven Way to Build Good Habits & Break Bad Ones is a self-help book by James Clear, published in 2018. The book provides a framework for improving every day through small, incremental changes. Clear argues that big changes come from the compound effect of hundreds of small decisions - atomic habits. He introduces the Four Laws of Behavior Change: make it obvious, make it attractive, make it easy, and make it satisfying. The book draws from biology, psychology, and neuroscience to create an easy-to-understand guide for making good habits inevitable and bad habits impossible. It has sold millions of copies worldwide and been translated into more than 60 languages.','cover_30_4b321809.jpg',6,6,0,NULL,'Rak B1','2026-10-20 03:29:57'),(58,'BK-0058','9780553380163','A Brief History of Time','Stephen Hawking','Bantam',1988,3,'A Brief History of Time: From the Big Bang to Black Holes is a popular-science book on cosmology by English physicist Stephen Hawking, first published in 1988. The book explains the structure, origin, development and eventual fate of the Universe in non-technical language, making complex concepts like space and time, black holes, and quantum mechanics accessible to general readers. Hawking addresses fundamental questions about the universe: Was there a beginning of time? Could time run backwards? Is the universe infinite or does it have boundaries? The book examines cosmological theories from Aristotle and Ptolemy through Einstein to modern concepts like the Big Bang, black holes, and string theory. It became a bestseller and remained on the London Sunday Times bestseller list for a record-breaking 237 weeks.','cover_30_ec89f4c4.jpg',3,3,0,NULL,'Rak C1','2026-10-20 03:29:57'),(59,'BK-0059','9780345539434','Cosmos','Carl Sagan','Ballantine Books',1980,3,'Cosmos is a popular science book by astronomer and Pulitzer Prize-winning author Carl Sagan. The book, which accompanied the 1980 television series of the same name, explores the 15-billion-year history of cosmic evolution, transforming matter and life into consciousness, and how science and civilization grew up together. Sagan discusses topics ranging from the origins of life and the search for extraterrestrial intelligence to the future of humanity and the exploration of space. The book features 13 illustrated chapters corresponding to the episodes of the Cosmos television series. Sagan\'s poetic writing style makes complex scientific concepts accessible to general readers, inspiring generations to look at the stars with wonder and curiosity about our place in the universe.','cover_30_f55f116a.jpg',5,5,0,NULL,'Rak C1','2026-10-20 03:29:57'),(60,'BK-0060','9780199291151','The Selfish Gene','Richard Dawkins','Oxford University Press',1976,3,'The Selfish Gene is a 1976 book on evolution by the ethologist Richard Dawkins, in which he builds upon the principal theory of George C. Williams\'s Adaptation and Natural Selection (1966). Dawkins uses the term \'selfish gene\' as a way of expressing the gene-centered view of evolution, as opposed to the views focused on the organism and the group, popularizing ideas developed during the 1960s by W. D. Hamilton and others. From the gene-centered view, the more genetically two individuals are related, the more sense it makes for them to behave altruistically toward each other. The book also introduces the concept of \'memes\' as units of cultural transmission analogous to genes. It remains one of the most influential science books ever written, sparking debate about evolution, genetics, and the nature of life itself.','cover_30_9d822f0a.jpg',8,8,0,NULL,'Rak C1','2026-10-20 03:29:57'),(61,'BK-0061','9780132350884','Clean Code: A Handbook of Agile Software Craftsmanship','Robert C. Martin','Prentice Hall',2008,3,'Clean Code: A Handbook of Agile Software Craftsmanship is a software programming book by Robert C. Martin, published in 2008. The book is divided into three parts. The first part describes the principles, patterns, and practices of writing clean code. The second part consists of several case studies of increasing complexity, each an exercise in cleaning up code - transforming a code base that has some problems into one that is sound and efficient. The third part is a single chapter containing a list of heuristics and \'smells\' gathered while creating the case studies. Martin covers topics such as meaningful naming, functions, comments, formatting, objects and data structures, error handling, and unit testing. The book is essential reading for any software developer, engineer, or project manager who wants to write better, more maintainable code.','cover_30_a890b79a.jpg',8,8,0,NULL,'Rak C2','2026-10-20 03:29:57'),(62,'BK-0062','9780393317558','Guns, Germs, and Steel','Jared Diamond','W. W. Norton & Company',1997,4,'Guns, Germs, and Steel: The Fates of Human Societies is a 1997 transdisciplinary non-fiction book by Jared Diamond, professor of geography and physiology at the University of California, Los Angeles. In 1998, it won the Pulitzer Prize for general nonfiction and the Aventis Prize for Best Science Book. The book attempts to explain why Eurasian civilizations have survived and conquered others, while arguing against the idea that Eurasian hegemony is due to any form of Eurasian intellectual, moral, or inherent genetic superiority. Diamond argues that the gaps in power and technology between human societies do not reflect cultural or racial differences, but rather originate in environmental differences amplified by various positive feedback loops. He examines how geography, biology, and environmental factors shaped human history, from the domestication of plants and animals to the spread of diseases and the development of writing and technology.','cover_30_28e8e11b.jpg',2,2,0,NULL,'Rak D1','2026-10-20 03:29:57'),(63,'BK-0063','9780743226721','1776','David McCullough','Simon & Schuster',2005,4,'1776 is a book written by David McCullough, first published by Simon & Schuster in 2005. The work is a companion to McCullough\'s earlier biography of John Adams, and focuses on the events surrounding the start of the American Revolution. The book follows George Washington and the Continental Army through the pivotal year of 1776, when American independence was declared but the Revolutionary War was far from won. McCullough draws on extensive research in American and British archives to tell the human story of the soldiers, commanders, and citizens who lived through this crucial year. The narrative covers the Siege of Boston, the Battle of Long Island, the Battle of Trenton, and other key events, painting a vivid picture of the struggles and triumphs of the American Revolution.','cover_30_48459419.jpg',8,8,0,NULL,'Rak D1','2026-10-20 03:29:57'),(64,'BK-0064','9780671624200','The Rise and Fall of the Third Reich','William L. Shirer','Simon & Schuster',1960,4,'The Rise and Fall of the Third Reich: A History of Nazi Germany is a book by William L. Shirer chronicling the rise and fall of Nazi Germany from the birth of Adolf Hitler in 1889 to the end of World War II in 1945. It was first published in 1960 by Simon & Schuster in the United States. Shirer, a journalist and war correspondent, spent years in Germany observing the Nazi regime firsthand. The book draws on a vast array of captured German documents, the diaries of propaganda minister Joseph Goebbels, and other primary sources. It provides a detailed account of how Hitler rose to power, how the Nazi state functioned, and how Germany was ultimately defeated in World War II. The book won the National Book Award for nonfiction and remains one of the most important works on Nazi Germany.','cover_30_d0b268d6.jpg',1,1,0,NULL,'Rak D1','2026-10-20 03:29:57'),(65,'BK-0065','9780062397348','A People\'s History of the United States','Howard Zinn','Harper Perennial',1980,4,'A People\'s History of the United States is a 1980 non-fiction book by American historian and political scientist Howard Zinn. In the book, Zinn presented what he considered to be a different side of history from the more traditional fundamental nationalist glorification of America. Zinn portrays a side of American history that can largely be seen as the exploitation and manipulation of the majority by rigidly hierarchical systems, including government, religion, and the economy. The book covers American history from the perspective of ordinary people - Native Americans, slaves, workers, women, and minorities - rather than from the perspective of political and economic elites. It challenges readers to think critically about historical narratives and consider whose voices have been heard and whose have been silenced in the traditional telling of American history.','cover_30_6e09f55e.jpg',4,4,0,NULL,'Rak D2','2026-10-20 03:29:57'),(66,'BK-0066','9781101912379','The Silk Roads: A New History of the World','Peter Frankopan','Vintage',2015,4,'The Silk Roads: A New History of the World is a 2015 non-fiction work by the British historian Peter Frankopan. The book reorients our understanding of the world, pointing eastward toward the region between the East and the West that has long been the center of global trade, cultural exchange, and conflict. Frankopan traces the history of the Silk Roads from ancient times through the Middle Ages to the present day, showing how the exchange of goods, ideas, religions, and diseases along these routes shaped human civilization. The book covers topics from the spread of Buddhism and Islam to the Mongol Empire, the Black Death, the age of exploration, and the modern geopolitics of the Middle East and Central Asia. It offers a fresh perspective on world history that places Asia, not Europe, at the center of the story.','cover_30_11ed8f73.jpg',4,4,0,NULL,'Rak D2','2026-10-20 03:29:57'),(67,'BK-0067','9780143105870','The Quran','Various','Penguin Classics',2008,5,'The Quran is the central religious text of Islam, believed by Muslims to be a revelation from God (Allah). It is widely regarded as the finest work in classical Arabic literature. The Quran is divided into 114 chapters (surahs) which contain verses (ayahs). Muslims believe that the Quran was orally revealed by God to the final prophet, Muhammad, through the archangel Gabriel incrementally over a period of some 23 years, beginning in the month of Ramadan, when Muhammad was 40, and concluding in 632, the year of his death. The Quran is complemented by the hadith, accounts of the sayings and actions of Muhammad, which provide context for understanding and applying Quranic teachings. The text addresses a wide range of topics including theology, morality, law, personal conduct, and stories of previous prophets.','cover_30_5b99f862.jpg',10,10,0,NULL,'Rak E1','2026-10-20 03:29:57'),(68,'BK-0068','9780807014295','Man\'s Search for Meaning','Viktor E. Frankl','Beacon Press',1946,5,'Man\'s Search for Meaning is a 1946 book by Viktor Frankl chronicling his experiences as a prisoner in Nazi concentration camps during World War II, and describing his psychotherapeutic method, which involved identifying a purpose in life to feel positively about, and then immersively imagining that outcome. According to Frankl, the book intends to answer the question \'How was everyday life in a concentration camp reflected in the mind of the average prisoner?\' Part One constitutes Frankl\'s analysis of his experiences in the concentration camps. Part Two introduces his ideas of meaning and his theory called logotherapy. The book argues that we cannot avoid suffering but we can choose how to cope with it, find meaning in it, and move forward with renewed purpose. It has sold millions of copies worldwide and is considered one of the most influential books of the 20th century.','cover_30_bd0c58b4.jpg',1,1,0,NULL,'Rak E1','2026-10-20 03:29:57'),(69,'BK-0069','9780060652920','Mere Christianity','C. S. Lewis','HarperOne',1952,5,'Mere Christianity is a theological book by C. S. Lewis, adapted from a series of BBC radio talks made between 1941 and 1944, while Lewis was at Oxford during World War II. Considered a classic of Christian apologetics, the transcripts of the broadcasts originally appeared in print as three separate pamphlets: The Case for Christianity (1942), Christian Behaviour (1943), and Beyond Personality (1944). Lewis was an Anglican, but the book was deliberately ecumenical, divided into four parts: an outline of Christian doctrine, an explanation of Christian ethics, a discussion of Christian virtues and vices, and an exploration of the doctrine of the Trinity. Lewis presents Christianity not as a particular denomination but as the core beliefs common to nearly all Christians throughout history - hence the title \'Mere Christianity.\' The book remains one of the most popular introductions to Christian belief ever written.','cover_30_a7af0f01.jpg',9,9,0,NULL,'Rak E1','2026-10-20 03:29:57'),(70,'BK-0070','9780310349658','The Case for Christ','Lee Strobel','Zondervan',1998,5,'The Case for Christ is a 1998 Christian apologetics book by Lee Strobel. The book recounts Strobel\'s investigative journey from atheism to Christianity, using his background as an award-winning legal editor at the Chicago Tribune. Strobel cross-examines a dozen scholars with doctorates from schools like Cambridge, Princeton, and Brandeis, asking hard-hitting questions about the historical reliability of the New Testament, the evidence for Jesus\' resurrection, and whether Jesus truly claimed to be the Son of God. The book is structured around three main sections: examining the record, analyzing Jesus, and researching the resurrection. It presents a journalistic approach to investigating the claims of Christianity, appealing to both skeptics and believers seeking evidence for their faith.','cover_30_fd09c27f.jpg',10,10,0,NULL,'Rak E1','2026-10-20 03:29:57'),(71,'BK-0071','9780142410318','Charlie and the Chocolate Factory','Roald Dahl','Penguin Young Readers',1964,6,'Charlie and the Chocolate Factory is a 1964 children\'s novel by British author Roald Dahl. The story features the adventures of young Charlie Bucket inside the chocolate factory of eccentric chocolatier Willy Wonka. Charlie lives in poverty with his parents and four grandparents in a small house. When Willy Wonka announces that five golden tickets hidden in chocolate bars will grant the finders a tour of his mysterious factory and a lifetime supply of chocolate, Charlie finds the last ticket. Inside the factory, Charlie and four other children encounter bizarre rooms, Oompa-Loompas, and magical inventions. The other children, each representing a different vice (greed, gluttony, gum-chewing, television addiction), are comically eliminated one by one, leaving Charlie as the sole winner and heir to Wonka\'s chocolate empire.','cover_30_9c02d712.jpg',2,2,0,NULL,'Rak F1','2026-10-20 03:29:57'),(72,'BK-0072','9780064400558','Charlotte\'s Web','E. B. White','HarperCollins',1952,6,'Charlotte\'s Web is a 1952 children\'s novel by American author E. B. White, illustrated by Garth Williams. It tells the story of a pig named Wilbur and his friendship with a spider named Charlotte. When Wilbur is in danger of being slaughtered by the farmer, Charlotte writes messages praising Wilbur (such as \'Some Pig\') in her web to persuade the farmer to let him live. The novel explores themes of friendship, love, life, death, and the cycle of nature. Charlotte\'s Web was published on October 15, 1952, by Harper & Brothers. It has become one of the best-selling children\'s books of all time and has been adapted into multiple films, a stage musical, and a video game. The book was ranked as the top children\'s novel in a 2012 survey by School Library Journal.','cover_30_4ddea53a.jpg',4,4,0,NULL,'Rak F1','2026-10-20 03:29:57'),(73,'BK-0073','9780064431781','Where the Wild Things Are','Maurice Sendak','HarperCollins',1963,6,'Where the Wild Things Are is a 1963 children\'s picture book by American writer and illustrator Maurice Sendak, originally published by Harper & Row. The book has been adapted into other media, including an animated short in 1973, an opera, and a live-action feature film in 2009. The story follows a young boy named Max who, after dressing in his wolf costume, wreaks havoc through his house and is sent to bed without supper. Max\'s bedroom undergoes a mysterious transformation into a jungle environment, and he sails to an island inhabited by malicious beasts known as the \'Wild Things.\' After successfully intimidating the creatures, Max is hailed as the king of the Wild Things and enjoys a playful romp with his subjects. However, he decides to return home, to the Wild Things\' dismay, and finds his supper waiting for him in his room.','cover_30_c1b9aa1e.jpg',4,4,0,NULL,'Rak F1','2026-10-20 03:29:57'),(74,'BK-0074','9780544003415','The Lord of the Rings','J. R. R. Tolkien','Houghton Mifflin Harcourt',1954,7,'The Lord of the Rings is an epic high-fantasy novel by English author and scholar J. R. R. Tolkien. Set in Middle-earth, intended to be Earth at some distant time in the past, the story began as a sequel to Tolkien\'s 1937 children\'s book The Hobbit, but eventually developed into a much larger work. Written in stages between 1937 and 1949, The Lord of the Rings is one of the best-selling books ever written, with over 150 million copies sold. The title refers to the story\'s main antagonist, the Dark Lord Sauron, who had created the One Ring to rule the other Rings of Power given to Men, Dwarves, and Elves, in his campaign to conquer all of Middle-earth. The story follows the hobbit Frodo Baggins and his companions as they journey to destroy the One Ring in the fires of Mount Doom, where it was forged.','cover_30_be50a2.jpg',6,6,0,NULL,'Rak G1','2026-10-20 03:29:57'),(75,'BK-0075','9780553103540','A Game of Thrones','George R. R. Martin','Bantam Books',1996,7,'A Game of Thrones is the first novel in A Song of Ice and Fire, a series of epic fantasy novels by American author George R. R. Martin. It was first published on August 1, 1996. The novel won the 1997 Locus Award and was nominated for both the 1997 Nebula Award and the 1997 World Fantasy Award. The story is set in a fictional world, primarily on a continent called Westeros, and focuses on a dynastic war among several noble families for the Iron Throne. The novel is told through the third-person perspectives of nine characters, including members of House Stark, House Lannister, and House Targaryen. It blends political intrigue, warfare, and supernatural elements, including the return of magic and the threat of an ancient evil beyond the Wall in the far north.','cover_30_565ed389.jpg',3,3,0,NULL,'Rak G1','2026-10-20 03:29:57'),(76,'BK-0076','9780439064866','Harry Potter and the Chamber of Secrets','J. K. Rowling','Scholastic',1998,7,'Harry Potter and the Chamber of Secrets is a fantasy novel written by British author J. K. Rowling and the second novel in the Harry Potter series. The plot follows Harry\'s second year at Hogwarts School of Witchcraft and Wizardry, during which a series of messages on the walls of the school\'s corridors warn that the \'Chamber of Secrets\' has been opened and that the \'heir of Slytherin\' would kill all pupils who do not come from all-magical families. These threats are followed by attacks that leave residents of the school petrified. Throughout the year, Harry and his friends Ron Weasley and Hermione Granger investigate the attacks, confronting the dark legacy of Hogwarts founder Salazar Slytherin and a mysterious diary that belonged to Tom Marvolo Riddle. The book was published in the United Kingdom on 2 July 1998 by Bloomsbury and in the United States on 2 June 1999 by Scholastic Inc.','cover_30_67edc8e4.jpg',1,1,0,NULL,'Rak G1','2026-10-20 03:29:57'),(77,'BK-0077','9780756404741','The Name of the Wind','Patrick Rothfuss','DAW Books',2007,7,'The Name of the Wind, also called The Kingkiller Chronicle: Day One, is a heroic fantasy novel written by American author Patrick Rothfuss. It is the first book in the ongoing series The Kingkiller Chronicle, followed by The Wise Man\'s Fear. It was published on March 27, 2007 by DAW Books. The novel won a 2007 Quill Award and was nominated for the 2007 British Fantasy Award. The story follows Kvothe, a gifted young man who grows up to be the most notorious wizard in his world. Told in Kvothe\'s own voice, the novel follows his journey from a traveling troupe of performers to a precarious life as an orphan in a crime-ridden city, to his daring attempt to enter a legendary school of magic. It is a richly imagined tale of magic, music, and the power of storytelling.','cover_30_b6350dec.jpg',4,4,0,NULL,'Rak G2','2026-10-20 03:29:57'),(78,'BK-0078','9789792277289','Ronggeng Dukuh Paruk','Ahmad Tohari','Gramedia Pustaka Utama',1982,1,'Ronggeng Dukuh Paruk adalah salah satu mahakarya sastra Indonesia karya Ahmad Tohari yang mengangkat realitas sosial masyarakat pedesaan Jawa. Berlatar sebuah dukuh kecil bernama Dukuh Paruk yang dilanda kemiskinan dan kelaparan, novel ini mengisahkan perjalanan hidup Srintil, gadis yatim piatu yang dianugerahi bakat indang ronggeng dan dinobatkan menjadi penari ronggeng baru di desanya.\n\nNamun, di balik gemerlap status dan pujaan para lelaki penikmat tarian, Srintil harus membayar harga yang teramat mahal atas tubuh dan kebebasannya melalui tradisi bukak-klambu. Di sisi lain, Rasus, sahabat masa kecil Srintil yang menaruh cinta tulus padanya, merasa tersakiti dan memutuskan merantau menjadi tentara.\n\nKonflik batin, pergulatan adat lokal, serta hempasan gelombang pergolakan politik tahun 1965 di Indonesia menjadi benang merah yang mengharukan dalam trilogi legendaris ini.','cover_gen_6ad6e1d7635d8.jpg',6,6,0,NULL,'Rak A2','2026-10-20 03:36:58'),(79,'BK-0079','9789794071373','Tenggelamnya Kapal Van der Wijck','Buya Hamka','Bulan Bintang',1938,1,'Tenggelamnya Kapal Van der Wijck merupakan novel roman legendaris karya ulama sekaligus sastrawan besar Indonesia, Prof. Dr. Haji Abdul Malik Karim Amrullah (Buya Hamka). Kisah ini berpusat pada jalinan cinta murni antara Zainuddin, pemuda miskin berdarah campuran Minangkabau-Bugis, dan Hayati, seorang gadis jelita keturunan bangsawan murni di tanah Minang.\n\nCinta tulus keduanya harus kandas di hadapan tembok adat Minangkabau yang kaku dan memandang Zainuddin sebagai orang luar yang tak bertali darah adat. Hayati dipaksa menikah dengan Aziz, pemuda kaya dari keluarga terpandang yang ternyata berperangai buruk.\n\nKetika nasib berputar dan Zainuddin bangkit menjadi pengarang termasyhur di Jawa, takdir kembali mempertemukan mereka dalam situasi yang penuh kepedihan hingga berujung pada tragedi tenggelamnya kapal mewah Van der Wijck di perairan Laut Jawa.','cover_gen_6ad6e1da1b17d.jpg',5,5,0,NULL,'Rak A2','2026-10-20 03:37:00'),(80,'BK-0080','9789792281415','Gadis Kretek','Ratih Kumala','Gramedia Pustaka Utama',2012,1,'Gadis Kretek karya Ratih Kumala adalah novel berlatar sejarah industri tembakau dan rokok kretek di Jawa pada masa pasca-kemerdekaan hingga era modern. Cerita dimulai saat Soeraja, pemilik pabrik Kretek Djagad Raja yang sedang sekarat, tiba-tiba menyebut nama seorang perempuan misterius bernama Jeng Yah, bukan nama istrinya.\n\nKetiga putra Soeraja—Tegar, Karim, dan Lebas—lantas menjelajahi pelosok Jawa Tengah dan Jawa Timur untuk melacak siapa sebenarnya sosok Jeng Yah tersebut. Penelusuran ini membuka tabir persaingan bisnis keluarga pembuat saus kretek, kisah cinta segitiga yang rumit, serta intrik pengkhianatan di tengah gejolak sejarah bangsa Indonesia.\n\nNovel ini menyajikan riset mendalam tentang tradisi linting tembakau Nusantara dengan gaya penceritaan yang memikat dan penuh aroma rempah masa lalu.','cover_gen_6ad6e1dc558cf.jpg',7,7,0,NULL,'Rak A3','2026-10-20 03:37:00'),(81,'BK-0081','9786020312583','Cantik Itu Luka','Eka Kurniawan','Gramedia Pustaka Utama',2002,1,'Cantik Itu Luka adalah novel debut mendunia dari sastrawan Eka Kurniawan yang memadukan realisme magis, sejarah kelam kolonialisme, dan fabel satir khas Nusantara. Cerita berawal dengan kalimat pembuka yang terkenal: \"Suatu sore, sembilan belas tahun setelah hari pemakamannya, Dewi Ayu bangkit dari kuburnya.\"\n\nDewi Ayu, perempuan berdarah campuran Belanda yang dijadikan wanita penghibur pada masa penjajahan Jepang, melahirkan empat anak perempuan. Tiga putri pertamanya mewarisi kecantikan luar biasa yang membawa malapetaka bagi hidup mereka, sementara putri bungsunya yang terlahir dengan paras sangat buruk rupa justru dinamai Cantik.\n\nMelalui kisah keluarga Dewi Ayu di kota fiktif Halimunda, novel ini membongkar luka sejarah perang, komunisme, bandit kota, serta represi militer dengan humor gelap dan narasi yang luar biasa memikat.','cover_gen_6ad6e1dc5c21d.jpg',6,6,0,NULL,'Rak A3','2026-10-20 03:37:03'),(82,'BK-0082','9780140256352','Bumi Manusia','Pramoedya Ananta Toer','Lentera Dipantara',1980,1,'Bumi Manusia adalah mahakarya pertama dari Tetralogi Buru yang ditulis oleh Pramoedya Ananta Toer saat menjalani masa pengasingan di Pulau Buru. Novel ini mengambil latar Hindia Belanda pada pergantian abad ke-20 dan mengisahkan Minke, pemuda pribumi cerdas yang berkesempatan mengenyam pendidikan di H.B.S. Surabaya.\n\nMinke jatuh cinta pada Annelies Mellema, putri blasteran Indo-Eropa dari seorang Nyai perkasa bernama Nyai Ontosoroh. Di tengah perlawanannya terhadap diskriminasi rasial, hierarki feodal Jawa, dan ketidakadilan hukum kolonial Eropa, Minke tumbuh menjadi pribadi yang berani bersuara lewat tulisan.\n\nBumi Manusia adalah epos kebangkitan kesadaran nasional yang menggugah jiwa pembaca mengenai martabat, cinta, dan kemanusiaan.','cover_gen_6ad6e1df40ea2.jpg',8,8,0,NULL,'Rak A3','2026-10-20 03:37:06'),(83,'BK-0083','9786024125189','Filosofi Teras','Henry Manampiring','Penerbit Buku Kompas',2018,2,'Filosofi Teras karya Henry Manampiring merupakan pengantar filsafat Stoikisme Yunani-Romawi kuno yang dikemas secara segar, praktis, dan sangat relevan bagi generasi modern yang kerap dirundung rasa cemas, stres, dan overthinking.\n\nBuku ini memperkenalkan konsep inti Dikotomi Kendali: membedakan dengan tegas apa hal-hal yang berada di bawah kendali kita (pikiran, tindakan, respon) dan hal-hal di luar kendali kita (opini orang lain, reputasi, masa depan, cuaca). Ditulis dengan gaya bahasa kasual disertai ilustrasi jenaka serta survei kondisi mental masyarakat urban Indonesia.\n\nBuku ini membimbing pembaca meraih ketenangan batin (ataraxia) di tengah dunia yang bising dan penuh ketidakpastian.','cover_gen_6ad6e1e220690.jpg',9,9,0,NULL,'Rak B2','2026-10-20 03:37:06'),(84,'BK-0084','9780062457714','Sebuah Seni untuk Bersikap Bodo Amat','Mark Manson','Grasindo',2016,2,'Sebuah Seni untuk Bersikap Bodo Amat (The Subtle Art of Not Giving a F*ck) karya Mark Manson adalah buku pengembangan diri yang mendobrak pendekatan motivasi klise. Alih-alih menyuruh pembaca untuk selalu berpikir positif tanpa henti, Manson justru mengajak kita menerima kenyataan bahwa hidup ini keras, penuh tantangan, dan kegagalan adalah bagian tak terpisahkan dari eksistensi manusia.\n\nManson menegaskan bahwa bersikap \"bodo amat\" bukan berarti menjadi apatis, melainkan bijak memilih hal-hal apa saja yang benar-benar layak dipedulikan dan mana yang harus dilepaskan.\n\nDengan bahasa lugas, metafora tajam, dan humor sinis namun mencerahkan, buku ini mengajarkan cara menetapkan nilai-nilai hidup yang sehat serta berdamai dengan ketidaksempurnaan diri.','cover_gen_6ad6e1e228a77.jpg',8,8,0,NULL,'Rak B2','2026-10-20 03:37:08'),(85,'BK-0085','9780316017923','Outliers: Rahasia di Balik Kesuksesan','Malcolm Gladwell','Gramedia Pustaka Utama',2008,2,'Dalam Outliers: The Story of Success, jurnalis investigatif Malcolm Gladwell membongkar mitos bahwa kesuksesan luar biasa hanya berasal dari bakat alami, kejeniusan murni, dan kerja keras individu semata. Gladwell mengamati orang-orang istimewa (outliers)—seperti Bill Gates, The Beatles, hingga para atlet kelas dunia—dan mengungkap faktor-faktor tersembunyi yang membentuk keberhasilan mereka.\n\nMulai dari konsep Aturan 10.000 Jam latihan terfokus, pengaruh budaya leluhur, warisan keluarga, hingga keberuntungan waktu lahir dan kesempatan langka yang hadir di sekitar mereka.\n\nDitulis dengan gaya bercerita memikat yang didukung data sosiologis, Outliers mengubah cara pandang kita terhadap bagaimana masyarakat dapat membuka peluang bagi lahirnya individu-individu berprestasi tinggi.','cover_gen_6ad6e1e4da427.jpg',6,6,0,NULL,'Rak B3','2026-10-20 03:37:09'),(86,'BK-0086','9780201616224','The Pragmatic Programmer','Andrew Hunt, David Thomas','Addison-Wesley Professional',1999,3,'The Pragmatic Programmer adalah kitab suci bagi para rekayasawan perangkat lunak di seluruh dunia. Buku ini tidak terikat pada satu bahasa pemrograman atau teknologi tertentu, melainkan mengajarkan filosofi inti, kebiasaan kerja, dan seni memprogram secara adaptif, modular, dan berkelanjutan.\n\nAndrew Hunt dan David Thomas menyajikan prinsip-prinsip abadi seperti DRY (Don\'t Repeat Yourself), manajemen hutang teknis, testing otomatis, ortogonalitas kode, hingga cara berkomunikasi efektif dalam tim perekayasa.\n\nDitujukan bagi pemula hingga arsitek sistem kawakan, buku ini mengasah kemampuan teknis sekaligus mentalitas profesional untuk membangun perangkat lunak yang tangguh, elegan, dan mudah dipelihara.','cover_gen_6ad6e1e5b360b.jpg',5,5,0,NULL,'Rak C2','2026-10-20 03:37:10'),(87,'BK-0087','9780201485677','Refactoring: Improving the Design of Existing Code','Martin Fowler','Addison-Wesley Professional',1999,3,'Refactoring karya Martin Fowler mendefinisikan standar industri bagaimana seorang programmer harus merawat basis kode yang kian membengkak. Refactoring adalah proses mengubah struktur internal perangkat lunak tanpa mengubah perilaku eksternalnya, dengan tujuan meningkatkan keterbacaan kode dan menurunkan biaya pemeliharaan di masa mendatang.\n\nFowler memperkenalkan konsep \"code smells\"—tanda-tanda visual dan struktural pada kode yang membutuhkan perbaikan—disertai katalog lengkap teknik refactoring langkah demi langkah, mulai dari Extract Function, Move Field, hingga Replace Conditional with Polymorphism.\n\nDilengkapi contoh kasus konkret dan pentingnya rangkaian tes otomatis, buku ini wajib dibaca oleh setiap pengembang yang ingin menulis kode berkualitas profesional.','cover_gen_6ad6e1e661e86.jpg',4,4,0,NULL,'Rak C2','2026-10-20 03:37:12'),(88,'BK-0088','9780201633610','Design Patterns: Elements of Reusable Object-Oriented Software','Erich Gamma, Richard Helm, Ralph Johnson, John Vlissides','Addison-Wesley Professional',1994,3,'Sering dijuluki sebagai buku \"Gang of Four\" (GoF), karya monumental ini adalah tonggak sejarah perancangan perangkat lunak berorientasi objek. Buku ini mengkristalisasikan 23 pola desain klasik yang terbagi menjadi tiga kategori utama: Creational (pembentukan objek), Structural (komposisi kelas/objek), dan Behavioral (interaksi antar objek).\n\nPola-pola terkenal seperti Singleton, Factory Method, Observer, Strategy, Adapter, dan Composite diulas secara mendalam beserta motivasi penggunaan, diagram struktur, dan contoh implementasinya.\n\nPemahaman terhadap pola-pola ini memungkinkan para insinyur perangkat lunak merancang arsitektur sistem yang fleksibel, dapat digunakan kembali, dan siap menghadapi perubahan kebutuhan sistem yang kompleks.','cover_gen_6ad6e1e8bd678.jpg',5,5,0,NULL,'Rak C3','2026-10-20 03:37:15'),(89,'BK-0089','9789799101242','Nusantara: Sejarah Indonesia','Bernard H.M. Vlekke','Kepustakaan Populer Gramedia (KPG)',2008,4,'Nusantara: Sejarah Indonesia karya sejarawan terkemuka Bernard H.M. Vlekke merupakan salah satu rujukan komprehensif tertua dan paling dihormati dalam historiografi kepulauan Indonesia. Buku ini merekam jejak perjalanan panjang bangsa Nusantara mulai dari zaman prasejarah, masa kejayaan kerajaan maritim bercorak Hindu-Buddha seperti Sriwijaya dan Majapahit, hingga persebaran Islam ke berbagai pelosok negeri.\n\nVlekke juga menelaah secara objektif kedatangan bangsa Barat, perebutan monopoli rempah-rempah oleh VOC, sistem tanam paksa era Hindia Belanda, hingga bangkitnya nasionalisme Indonesia pada awal abad ke-20.\n\nDitulis dengan gaya bertutur naratif yang runtut dan ilmiah, karya ini memberikan pemahaman mendalam tentang akar identitas geografis, kultural, dan geopolitik Indonesia.','cover_gen_6ad6e1eb9c3f1.jpg',6,6,0,NULL,'Rak D2','2026-10-20 03:37:15'),(90,'BK-0090','9789794213377','Sejarah Peradaban Islam','Prof. Dr. Badri Yatim, M.A.','Rajawali Pers',2014,4,'Buku Sejarah Peradaban Islam karya Prof. Dr. Badri Yatim, M.A. merupakan teks standar akademis yang menyajikan panorama perjalanan peradaban Islam secara kronologis dan berimbang. Dimulai dari kondisi masyarakat jazirah Arab pra-Islam, era kenabian Muhammad SAW, hingga masa Khulafaur Rasyidin yang meletakkan sendi-sendi keadilan dan kepemimpinan umat.\n\nBuku ini kemudian menguraikan ekspansi kebudayaan serta kemajuan sains pada masa Dinasti Umayyah di Damaskus dan Andalusia, puncak keemasan intelektual era Dinasti Abbasiyah di Baghdad, kemunduran akibat serbuan Mongol, hingga kebangkitan tiga kerajaan besar Islam (Usmani di Turki, Safawi di Persia, dan Mughal di India) serta proses masuknya Islam ke Nusantara.\n\nSangat informatif bagi pelajar, mahasiswa, dan pembaca umum yang mendalami sejarah kebudayaan dunia.','cover_gen_6ad6e1eba4646.jpg',7,7,0,NULL,'Rak D3','2026-10-20 03:37:15'),(91,'BK-0091','9789793269009','Gagasan Islamisasi Ilmu Pengetahuan','Prof. Dr. Syed Muhammad Naquib al-Attas','Risalah Gusti',1995,5,'Gagasan Islamisasi Ilmu Pengetahuan merupakan karya filosofis penting dari pemikir terkemuka dunia Islam kontemporer, Prof. Dr. Syed Muhammad Naquib al-Attas. Buku ini membedah krisis epistemologi yang dihadapi peradaban modern ketika ilmu pengetahuan terpisah dari nilai-nilai ketuhanan dan moralitas metafisik (sekularisasi ilmu).\n\nAl-Attas menawarkan konsep de-westernisasi dan Islamisasi ilmu pengetahuan: sebuah proses pembebasan akal budi dari kerangka berpikir sekular dan memasukkan konsep-konsep kunci Islam ke dalam pemahaman ilmu pengetahuan kontemporer.\n\nBuku ini mengupas konsep adab, ta\'dib, hakikat kebahagiaan (sa\'adah), serta kedudukan manusia sebagai khalifah yang bertanggung jawab atas pengetahuannya di hadapan Sang Pencipta.','cover_gen_6ad6e1ebac36f.jpg',4,4,0,NULL,'Rak E2','2026-10-20 03:37:15'),(92,'BK-0092','9789799655530','Tafsir Al-Azhar: Jilid Pilihan','Buya Hamka','Gema Insani',1982,5,'Tafsir Al-Azhar adalah adikarya monumental dari Buya Hamka yang dirampungkan ketika beliau menjadi tahanan politik di era Orde Lama. Memadukan tafsir bil-ma\'tsur (riwayat) dan bil-ma\'qul (ijtihad rasional), Hamka menghadirkan penjelasan ayat-ayat suci Al-Qur\'an dengan bahasa Indonesia sastrawi yang elok, santun, dan mudah dicerna oleh masyarakat awam sekalipun.\n\nKeunikan Tafsir Al-Azhar terletak pada pendekatan sosio-kulturalnya; Hamka kerap menghubungkan konteks ayat Al-Qur\'an dengan realitas sosial kemasyarakatan, adat istiadat Nusantara, serta dinamika modernitas dan kebangsaan.\n\nTafsir ini menjadi pelita rohani bagi jutaan umat di Asia Tenggara yang merindukan pemahaman Al-Qur\'an yang membumi, moderat, dan menyejukkan.','cover_gen_6ad6e1ebb45be.jpg',6,6,0,NULL,'Rak E2','2026-10-20 03:37:15'),(93,'BK-0093','9789792248616','Negeri 5 Menara','Ahmad Fuadi','Gramedia Pustaka Utama',2009,6,'Negeri 5 Menara adalah novel inspiratif berbasis kisah nyata karya Ahmad Fuadi tentang enam santri dari pelosok nusantara yang bersahabat erat di Pesantren Pondok Madani, Ponorogo, Jawa Timur. Alif Fikri, pemuda asal Danau Maninjau yang awalnya terpaksa masuk pesantren, menemukan dunia baru yang penuh kedisiplinan, mimpi besar, dan persaudaraan sejati.\n\nBersama lima sahabatnya—Raja, Said, Dulmajid, Atang, dan Baso—mereka terpesona oleh mantra sakti \"Man jadda wajada\" (siapa yang bersungguh-sungguh pasti akan berhasil). Sembari duduk di bawah bayang-bayang menara masjid pesantren setiap sore, mereka melukiskan impian untuk menaklukkan benua-benua di dunia.\n\nNovel ini kaya akan pesan keteguhan tekad, toleransi, bakti pada orang tua, dan indahnya menuntut ilmu.','cover_gen_6ad6e1ebbbb74.jpg',8,8,0,NULL,'Rak F2','2026-10-20 03:37:18'),(94,'BK-0094','9786025734939','Si Anak Badai','Tere Liye','Republika Penerbit',2019,6,'Si Anak Badai merupakan bagian dari seri novel anak Nusantara karya Tere Liye yang bercerita tentang Zaenal (Za) dan geng petualangnya di sebuah perkampungan nelayan bernama Muara Manau. Bersama ketiga sahabatnya—Malik, Ode, dan Awang—Zaenal tumbuh menjadi anak pesisir yang tangkas bersampan, berenang di sungai deras, dan berani menghadapi deburan ombak.\n\nNamun ketenteraman kampung mereka terancam ketika sebuah perusahaan pelabuhan raksasa hendak menggusur rumah panggung para nelayan. Dengan kepolosan, kecerdikan khas anak-anak, dan rasa cinta yang mendalam terhadap tanah kelahiran, Zaenal dan kawan-kawannya menyusun strategi untuk melindungi kampung mereka dari cengkeraman korporasi serakah.\n\nSebuah kisah masa kecil yang menghangatkan hati, penuh tawa, petualangan alam, dan nilai persahabatan sejati.','cover_gen_6ad6e1ee10506.jpg',7,7,0,NULL,'Rak F2','2026-10-20 03:37:20'),(95,'BK-0095','9780064471046','The Chronicles of Narnia: Sang Singa, sang Penyihir, dan Lemari','C. S. Lewis','Gramedia Pustaka Utama',1950,7,'Sang Singa, sang Penyihir, dan Lemari (The Lion, the Witch and the Wardrobe) adalah novel fantasi klasik karya C. S. Lewis yang telah memikat imajinasi jutaan pembaca lintas generasi. Berlatar masa Perang Dunia II di Inggris, empat bersaudara Pevensie—Peter, Susan, Edmund, dan Lucy—diungsikan ke rumah pedesaan seorang profesor eksentrik.\n\nSaat bermain petak umpet, Lucy secara tak sengaja melangkah menembus bagian belakang sebuah lemari pakaian tua dan menemukan gerbang menuju dunia ajaib Narnia: negeri yang dikutuk dalam musim dingin abadi tanpa perayaan Natal oleh Penyihir Putih yang kejam.\n\nBersama sang singa agung Aslan, keempat anak manusia ini harus memenuhi nubuat kuno untuk membebaskan Narnia dari belenggu kegelapan melalui keberanian, pengorbanan, dan kesetiaan.','cover_gen_6ad6e1f08d9e8.jpg',6,6,0,NULL,'Rak G2','2026-10-20 03:37:23'),(96,'BK-0096','9786020385914','Komet','Tere Liye','Gramedia Pustaka Utama',2018,7,'Komet adalah buku kelima dalam serial dunia paralel legendaris karya Tere Liye (setelah Bumi, Bulan, Matahari, dan Bintang). Melanjutkan petualangan tiga remaja berkekuatan khusus—Raib yang bisa menghilang, Seli yang mengendalikan petir, dan Ali si genius yang dapat bertransformasi menjadi beruang raksasa—kini mereka harus berlomba menemukan Pulau Komet sebelum si Tanpa Mahkota berhasil merebut kekuatannya.\n\nDi Pulau Komet yang dipenuhi teka-teki magis, flora dan fauna fantastis, serta ujian ketulusan hati, mereka harus memecahkan petunjuk demi petunjuk tanpa mengandalkan kekuatan bertarung semata.\n\nNovel fantasi petualangan berkecepatan tinggi ini menyuguhkan aksi heroik, teka-teki logika yang cerdas, dan pelajaran berharga mengenai arti kesetiaan dalam persahabatan.','cover_gen_6ad6e1f3c5dfc.jpg',6,6,0,NULL,'Rak G2','2026-10-20 03:37:26'),(97,'BK-0097','9780786838653','Percy Jackson & the Olympians: Pencuri Petir','Rick Riordan','Mizan Fantasi',2005,7,'Pencuri Petir (The Lightning Thief) karya Rick Riordan adalah novel fantasi petualangan modern yang memadukan mitologi Yunani kuno dengan kehidupan anak muda abad ke-21. Percy Jackson adalah anak berusia dua belas tahun yang menderita disleksia dan ADHD, yang kerap dicap sebagai anak bermasalah di sekolahnya.\n\nSemuanya berubah drastis ketika guru matematikanya berubah menjadi monster bersayap dan menyerangnya. Percy segera menyadari kebenaran mengejutkan: para dewa Olympus masih hidup dan bertakhta di lantai 600 Empire State Building di New York, dan dirinya adalah seorang demigod (blasteran manusia dan dewa), putra Poseidon sang dewa laut.\n\nKetika petir azimat Zeus dicuri, Percy dituduh sebagai pelakunya dan harus mengarungi perjalanan melintasi Amerika Serikat untuk menangkap pencuri sejati dan mencegah pecahnya perang antar dewa.','cover_gen_6ad6e1f6a8c54.jpg',8,8,0,NULL,'Rak G3','2026-10-20 03:37:29'),(98,'BK-0098','9780674729018','Make It Stick: The Science of Successful Learning','Peter C. Brown, Henry L. Roediger III, Mark A. McDaniel','Harvard University Press',2014,8,'Make It Stick adalah buku terobosan karya dua profesor psikologi kognitif dan seorang penulis yang merangkum riset ilmiah terkini tentang cara otak manusia memproses dan mengingat informasi secara permanen.\n\nBuku ini mematahkan mitos belajar tradisional seperti membaca ulang berulang kali dan menyorot teks dengan stabilo, yang ternyata hanya menciptakan ilusi pemahaman semu. Sebaliknya, teknik seperti retrieval practice (mengingat kembali secara aktif), spaced repetition (pengulangan berjarak), dan interleaving (mempelajari topik campuran) terbukti secara empiris melipatgandakan retensi ingatan jangka panjang.\n\nSangat direkomendasikan bagi pelajar, pendidik, dan pembelajar seumur hidup yang ingin meningkatkan efisiensi belajar secara nyata.','cover_edu_6ad6e6520f12f.jpg',7,7,0,NULL,'Rak P1','2026-10-20 03:56:03'),(99,'BK-0099','9780143132547','Learning How to Learn: Cara Menjadi Juara dalam Belajar','Barbara Oakley, Ph.D. & Terrence Sejnowski, Ph.D.','TarcherPerigee',2018,8,'Diadaptasi dari salah satu kursus online (MOOC) terpopuler sepanjang masa di dunia, Learning How to Learn membedah cara kerja otak kita dalam dua mode utama: mode fokus (focused mode) dan mode baur (diffuse mode).\n\nDr. Barbara Oakley membagikan kiat konkret mengatasi prokrastinasi (kebiasaan menunda-nunda) dengan teknik Pomodoro, membangun \'chunking\' informasi agar materi rumit menjadi mudah dipahami, serta memanfaatkan waktu tidur untuk konsolidasi memori saraf.\n\nDitulis dengan gaya santai dan ramah bagi remaja maupun mahasiswa, buku ini memberikan peta jalan untuk menguasai mata pelajaran apa pun yang sebelumnya dianggap menakutkan.','cover_edu_6ad6e653dca7d.jpg',8,8,0,NULL,'Rak P1','2026-10-20 03:56:06'),(100,'BK-0100','9789799471239','Pedagogi Kaum Tertindas','Paulo Freire','LP3ES',1968,8,'Pedagogi Kaum Tertindas (Pedagogy of the Oppressed) adalah karya monumental filsuf pendidikan asal Brasil, Paulo Freire, yang mengguncang paradigma pendidikan dunia. Freire mengkritik keras konsep \'pendidikan gaya bank\' (banking concept of education), di mana guru bertindak sebagai depositor yang pasif menyuapi pengetahuan kepada siswa yang dianggap sebagai bejana kosong.\n\nSebagai alternatif, Freire mengusung \'pendidikan hadap masalah\' (problem-posing education) yang bersifat dialogis, memanusiakan, dan membebaskan. Pendidikan harus menjadi alat pembebasan kesadaran (konsientisasi) agar kaum tertindas mampu mengenali struktur penindasan di sekelilingnya dan bergerak mengubah realitas hidup mereka menuju keadilan sejati.','cover_edu_6ad6e65662e68.jpg',5,5,0,NULL,'Rak P1','2026-10-20 03:56:06'),(101,'BK-0101','9789796868841','Active Learning: 101 Strategi Pembelajaran Aktif','Melvin L. Silberman','Nuansa Cendekia',2006,8,'Buku legendaris karya Dr. Melvin L. Silberman ini menghadirkan 101 teknik pembelajaran aktif yang siap diterapkan di ruang kelas maupun pelatihan daring untuk mengubah suasana kelas yang pasif menjadi dinamis dan partisipatif.\n\nBerdasarkan adagium Konfusius: \'Apa yang saya dengar, saya lupa; apa yang saya lihat, saya ingat; apa yang saya kerjakan, saya pahami,\' Silberman merinci strategi diskusi kelompok, simulasi permainan peran, kuis kolaboratif, dan teknik tanya-jawab yang merangsang keterlibatan mental serta fisik siswa.\n\nBuku ini menjadi pegangan wajib bagi para guru, dosen, dan instruktur pelatihan profesional untuk menghidupkan interaksi belajar yang menyenangkan.','cover_edu_6ad6e65669ca7.jpg',6,6,0,NULL,'Rak P1','2026-10-20 03:56:06'),(102,'BK-0102','9789794332306','Quantum Learning: Membiasakan Belajar Nyaman dan Menyenangkan','Bobbi DePorter & Mike Hernacki','Kaifa',1999,8,'Quantum Learning merangkum model pembelajaran akseleratif dari SuperCamp di Amerika Serikat yang menggabungkan sugestologi, teknik NLP (Neuro-Linguistic Programming), dan riset fungsi otak kiri-kanan.\n\nBuku ini mengajarkan cara mengenali gaya belajar dominan (visual, auditori, kinestetik), teknik mencatat peta pikiran (mind mapping), cara membaca cepat (speed reading) dengan pemahaman tinggi, serta penciptaan atmosfer belajar yang membangkitkan rasa percaya diri.\n\nDengan memadukan unsur kenyamanan dan tantangan, Quantum Learning mengubah paradigma belajar dari suatu beban kewajiban menjadi pengalaman yang menggembirakan.','cover_edu_6ad6e65671b8d.jpg',7,7,0,NULL,'Rak P1','2026-10-20 03:56:06'),(103,'BK-0103','9786020454375','Mindset: Mengubah Pola Pikir untuk Perubahan Besar','Carol S. Dweck, Ph.D.','Baca (Penerbit Lentera)',2006,8,'Berdasarkan riset puluhan tahun di Stanford University, psikolog Carol S. Dweck memperkenalkan perbedaan mendasar antara Fixed Mindset (pola pikir tetap) dan Growth Mindset (pola pikir berkembang) dalam mempengaruhi capaian belajar dan masa depan seseorang.\n\nOrang dengan pola pikir berkembang meyakini bahwa kemampuan dan kecerdasan dapat ditempa melalui dedikasi, kerja keras, dan strategi belajar yang tepat. Bagi mereka, kegagalan bukanlah cerminan batas kecerdasan, melainkan batu loncatan berharga untuk berkembang.\n\nBuku ini menjadi rujukan utama para pendidik modern dalam memberikan umpan balik (feedback) positif yang memicu semangat pantang menyerah bagi peserta didik.','cover_edu_6ad6e6567a394.jpg',9,9,0,NULL,'Rak P2','2026-10-20 03:56:06'),(104,'BK-0104','9789797693893','Model-Model Pembelajaran: Mengembangkan Profesionalisme Guru','Prof. Dr. Rusman, M.Pd.','Rajawali Pers',2012,8,'Model-Model Pembelajaran karya Prof. Dr. Rusman merupakan buku teks komprehensif yang menguraikan sintaks, prinsip reaksi, sistem pendukung, dan dampak instruksional dari berbagai model pembelajaran inovatif yang relevan dengan kurikulum nasional.\n\nMulai dari Problem-Based Learning (PBL), Project-Based Learning (PjBL), Discovery/Inquiry Learning, hingga ragam model pembelajaran kooperatif (Jigsaw, STAD, TGT). Setiap model dibedah secara teoritis disertai langkah-langkah implementasi praktis di kelas dan format lembar kerja siswa.\n\nBuku ini sangat esensial bagi calon pendidik dan guru profesional dalam menyusun Rencana Pelaksanaan Pembelajaran (RPP/Modul Ajar) yang bermutu.','cover_edu_6ad6e65690012.jpg',5,5,0,NULL,'Rak P2','2026-10-20 03:56:06'),(105,'BK-0105','9789790956483','Teori Belajar dan Pembelajaran','Prof. Dr. Ratna Wilis Dahar','Erlangga',2011,8,'Buku klasik ini mengulas fondasi teoritis psikologi belajar dari masa ke masa yang melandasi praktik pedagogi modern. Prof. Ratna Wilis Dahar memaparkan dengan jernih evolusi teori Behaviorisme (Pavlov, Skinner, Thorndike), Kognitivisme (Piaget, Bruner, Ausubel), hingga Konstruktivisme kontemporer.\n\nPenekanan khusus diberikan pada teori belajar bermakna (meaningful learning) David Ausubel dan hierarki belajar Robert Gagne yang menjadi dasar perancangan instruksional efektif di sekolah.\n\nBuku ini memberikan pemahaman mendasar mengapa suatu metode pembelajaran berhasil dan bagaimana menyesuaikan stimulasi instruksional dengan tahapan perkembangan kognitif siswa.','cover_edu_6ad6e656a0b8a.jpg',6,6,0,NULL,'Rak P2','2026-10-20 03:56:06'),(106,'BK-0106','9789793925769','Strategi Pembelajaran Berorientasi Standar Proses Pendidikan','Prof. Dr. Wina Sanjaya, M.Pd.','Kencana Prenada Media Group',2006,8,'Ditulis oleh pakar kurikulum Prof. Dr. Wina Sanjaya, buku ini mengulas prinsip-prinsip perencanaan dan penentuan strategi pembelajaran yang selaras dengan Standar Nasional Pendidikan.\n\nBuku ini membahas pemilihan metode ekspositori, inkuiri, strategi pemecahan masalah (SPMB), strategi peningkatan kemampuan berpikir (SPKB), serta strategi pembelajaran kontekstual (CTL). Diuraikan pula manajemen lingkungan kelas, pemanfaatan media pembelajaran berbasis teknologi, dan teknik evaluasi autentik.\n\nMenjadi referensi utama dalam mata kuliah perencanaan pembelajaran di seluruh fakultas keguruan dan ilmu pendidikan di Indonesia.','cover_edu_6ad6e656b253f.jpg',7,7,0,NULL,'Rak P2','2026-10-20 03:56:06'),(107,'BK-0107','9780132180276','The Systematic Design of Instruction','Walter Dick, Lou Carey, James O. Carey','Pearson',2015,8,'Model Dick and Carey adalah standar emas dalam dunia desain instruksional (Instructional Design) yang digunakan oleh para perancang kurikulum, pengembang konten e-learning, dan lembaga pelatihan korporasi global.\n\nBuku ini menguraikan metodologi 10 tahap perancangan sistem instruksional: mulai dari analisis kebutuhan tujuan instruksional, analisis pembelajar dan konteks, perumusan tujuan unjuk kerja, pengembangan instrumen penilaian acuan patokan, hingga evaluasi formatif dan sumatif.\n\nSebuah panduan sistematis, ilmiah, dan terukur untuk merancang materi ajar yang menjamin tercapainya kompetensi sasaran secara akurat.','cover_edu_6ad6e656bb084.jpg',5,5,0,NULL,'Rak P2','2026-10-20 03:56:07'),(108,'BK-0108','9789790104617','Dasar-Dasar Evaluasi Pendidikan','Prof. Dr. Suharsimi Arikunto','Bumi Aksara',2012,8,'Buku karya Prof. Dr. Suharsimi Arikunto ini adalah panduan paling populer di Indonesia mengenai teknik penyusunan, pengujian, dan pengolahan instrumen evaluasi hasil belajar siswa.\n\nDi dalamnya diuraikan secara gamblang cara menyusun kisi-kisi soal, membedakan tes formatif dan sumatif, menguji validitas dan reliabilitas instrumen secara manual maupun statistik, serta menganalisis tingkat kesukaran dan daya pembeda butir soal.\n\nSangat membantu guru dan pendidik dalam melakukan penilaian objektif yang transparan dan dapat dipertanggungjawabkan secara akademik.','cover_edu_6ad6e65775ba2.jpg',8,8,0,NULL,'Rak P3','2026-10-20 03:56:07'),(109,'BK-0109','9786022172772','Model Pembelajaran: Menciptakan Proses Belajar Mengajar yang Kreatif dan Efektif','Prof. Dr. Hamzah B. Uno, M.Pd.','Bumi Aksara',2014,8,'Buku ini membedah berbagai pendekatan mutakhir dalam merancang proses belajar-mengajar yang mampu menggugah motivasi intrinsik peserta didik di era digital.\n\nProf. Hamzah B. Uno mengkaji teori motivasi belajar, peranan media interaktif dan modul e-learning, serta strategi pembelajaran berbasis portofolio dan penugasan mandiri. Penulis menekankan pentingnya peran guru sebagai fasilitator yang menginspirasi, bukan sekadar penyampai materi searah.\n\nBuku ini memberikan bekal konseptual bagi guru untuk keluar dari rutinitas mengajar yang monoton menuju pembelajaran abad ke-21 yang kreatif.','cover_edu_6ad6e6577ecc8.jpg',6,6,0,NULL,'Rak P3','2026-10-20 03:56:07'),(110,'BK-0110','9780062852687','Ultralearning: Kuasai Keterampilan Sulit dengan Cepat','Scott H. Young','Harper Business',2019,8,'Scott H. Young, pemuda yang berhasil menuntaskan kurikulum ilmu komputer 4 tahun MIT dalam waktu kurang dari 12 bulan secara mandiri, merumuskan 9 prinsip dasar \'Ultralearning\'—strategi intensif untuk menguasai keterampilan sulit dan pengetahuan kompleks secara cepat.\n\nPrinsip-prinsip tersebut meliputi Meta-learning (membuat peta pengetahuan sebelum belajar), Directness (belajar langsung melalui praktik nyata), Drill (mengisolasi titik terlemah), dan Intuisi Feynman (menjelaskan konsep rumit dengan kata-kata sederhana).\n\nBuku ini menjadi panduan wajib bagi siapa saja yang ingin mengakselerasi karier dan memperluas kapabilitas diri di era otomatisasi.','cover_edu_6ad6e65789164.jpg',7,7,0,NULL,'Rak P3','2026-10-20 03:56:10'),(111,'BK-0111','9780134524177','Educational Psychology: Developing Learners','Jeanne Ellis Ormrod, Ph.D.','Pearson / Erlangga',2008,8,'Buku teks psikologi pendidikan terkemuka dunia karya Jeanne Ellis Ormrod ini menjembatani teori-teori riset ilmiah psikologis dengan aplikasi nyata di ruang kelas sekolah.\n\nBuku ini mengkaji secara mendalam perkembangan fisik, kognitif, linguistik, moral, dan sosio-emosional anak; dinamika motivasi belajar; perbedaan individual (anak berbakat dan berkebutuhan khusus); serta teknik pengelolaan kelas yang berkeadilan.\n\nDilengkapi berbagai studi kasus nyata, contoh interaksi guru-murid, dan saran strategi praktis untuk menciptakan lingkungan belajar yang mendukung pertumbuhan menyeluruh setiap peserta didik.','cover_edu_6ad6e65a97466.jpg',5,5,0,NULL,'Rak P3','2026-10-20 03:56:11'),(112,'BK-0112','9789795262480','Kurikulum dan Pembelajaran','Prof. Dr. Oemar Hamalik','Bumi Aksara',2007,8,'Karya rujukan klasik dari begawan pendidikan Indonesia, Prof. Dr. Oemar Hamalik, yang membahas kaitan integral antara desain kurikulum dan pelaksanaan proses pembelajaran di sekolah.\n\nMembahas asas-asas filosofis, psikologis, dan sosiologis pengembangan kurikulum, perumusan kompetensi lulusan, pemilihan bahan kajian, hingga strategi implementasi dan pemantauan mutu pembelajaran di lapangan.\n\nBuku ini memberi fondasi kokoh bagi para administrator sekolah, pengawas, kepala sekolah, dan guru dalam merancang pengalaman belajar siswa yang berdaya guna bagi kemajuan bangsa.','cover_edu_6ad6e65b444b6.jpg',6,6,0,NULL,'Rak P3','2026-10-20 03:56:11'),(113,'BK-0113','9780743277457','The Art of Learning: An Inner Journey to Optimal Performance','Josh Waitzkin','Free Press',2007,8,'Josh Waitzkin, anak ajaib catur yang kisahnya diangkat dalam film legendaris Searching for Bobby Fischer, kemudian membuktikan metodologinya dengan beralih haluan dan menjadi juara dunia seni bela diri Tai Chi Chuan.\n\nDalam buku reflektif ini, Waitzkin membongkar prinsip-prinsip psikologis untuk meraih keunggulan tertinggi (peak performance): cara belajar dari kekalahan, mengondisikan ketenangan pikiran di bawah tekanan ekstrem, memecah teknik kompleks menjadi gerak mikro-otomatis, dan mengubah rintangan menjadi bahan bakar pemicu kreativitas.\n\nSebuah memoar filosofis yang memukau tentang hakikat sejati proses belajar dan disiplin diri.','cover_edu_6ad6e65b4c59e.jpg',6,6,0,NULL,'Rak P4','2026-10-20 03:56:13'),(114,'BK-0114','9789796924370','Menjadi Guru Profesional: Menciptakan Pembelajaran Kreatif dan Menyenangkan','Prof. Dr. E. Mulyasa, M.Pd.','Remaja Rosdakarya',2005,8,'Buku pegangan para guru di Indonesia karya Prof. Dr. E. Mulyasa yang menguraikan empat pilar kompetensi guru profesional: pedagogik, kepribadian, sosial, dan profesional.\n\nMulyasa menekankan bahwa guru bukan sekadar profesi penyampai materi kurikulum, melainkan arsitek peradaban yang membentuk karakter generasi penerus bangsa. Diuraikan pula kiat menciptakan suasana kelas yang menyenangkan (joyful learning), membangkitkan gairah membaca siswa, serta mengatasi kejenuhan belajar.\n\nSangat aplikatif dan sarat motivasi untuk mendampingi guru dalam menjawab tuntutan sertifikasi dan profesionalisme pendidikan.','cover_edu_6ad6e65d9b001.jpg',7,7,0,NULL,'Rak P4','2026-10-20 03:56:13'),(115,'BK-0115','9780309070362','How People Learn: Brain, Mind, Experience, and School','National Research Council (John D. Bransford, et al.)','National Academy Press',2000,8,'Buku laporan konsensus ilmiah dari National Research Council Amerika Serikat ini mengumpulkan temuan-temuan kunci dari neurosains, psikologi kognitif, dan riset pendidikan terapan selama tiga dekade terakhir.\n\nFokus utamanya adalah membedah perbedaan cara kerja pikiran antara pakar (experts) dan pemula (novices), bagaimana pengetahuan sebelumnya (prior knowledge) mempengaruhi penerimaan materi baru, serta prinsip perancangan lingkungan belajar yang berpusat pada siswa, berpusat pada pengetahuan, dan berpusat pada komunitas.\n\nRujukan akademik paling otoritatif bagi siapa saja yang ingin memahami mekanisme belajar manusia secara komprehensif.','cover_edu_6ad6e65da2048.jpg',5,5,0,NULL,'Rak P4','2026-10-20 03:56:16'),(116,'BK-0116','9781455586691','Deep Work: Aturan untuk Meraih Sukses Terfokus di Dunia yang Bising','Cal Newport, Ph.D.','Grand Central Publishing',2016,8,'Profesor ilmu komputer Cal Newport mendefinisikan \'Deep Work\' sebagai kemampuan untuk berkonsentrasi tanpa distraksi pada tugas yang menuntut kemampuan kognitif tinggi—sebuah keahlian langka yang nilainya kian mahal di era kecerdasan buatan.\n\nNewport membeberkan bagaimana distraksi notifikasi gawai dan budaya kerja instan mengikis ketajaman otak manusia dalam menyerap konsep-konsep rumit. Buku ini memaparkan aturan praktis melatih kedisiplinan mental, merancang jadwal belajar mendalam yang bebas gangguan, serta teknik \'beristirahat produktif\' untuk memulihkan kapasitas otak.\n\nWajib dibaca oleh akademisi, peneliti, programmer, dan mahasiswa yang mendambakan hasil belajar optimal dalam waktu terukur.','cover_edu_6ad6e6603a43a.jpg',8,8,0,NULL,'Rak P4','2026-10-20 03:56:17'),(117,'BK-0117','9786022986423','Pendidikan Karakter & Pemikiran Ki Hadjar Dewantara','Ki Hadjar Dewantara (Kompilasi Majelis Luhur Tamansiswa)','UST Press / Tamansiswa',2013,8,'Kompilasi pemikiran Bapak Pendidikan Nasional Indonesia, Ki Hadjar Dewantara, yang memuat esensi sistem Among dengan semboyan legendaris: \'Ing ngarsa sung tulada, ing madya mangun karsa, tut wuri handayani\' (Di depan memberi teladan, di tengah membangun semangat, di belakang memberi dorongan).\n\nKi Hadjar menegaskan bahwa pendidikan sejati bukanlah mencetak robot pekerja, melainkan \'menuntun segala kodrat yang ada pada anak-anak agar mereka dapat mencapai keselamatan dan kebahagiaan yang setinggi-tingginya baik sebagai manusia maupun sebagai anggota masyarakat.\'\n\nKarya fundamental yang menjadi ruh dan inspirasi utama gerakan Merdeka Belajar dalam pendidikan modern Indonesia hari ini.','cover_edu_6ad6e6614a721.jpg',7,7,0,NULL,'Rak P4','2026-10-20 03:56:17');
